# Component: BQModel
class BQModel(Module):

    def __init__(self, dim_input_nodes, emb_size, dim_ff, activation_ff, nb_layers_encoder, nb_heads, activation_attention, dropout, batchnorm, problem='tsp'):
        assert problem == 'tsp' or problem == 'cvrp' or problem == 'kp' or (problem == 'op')
        super().__init__()
        self.problem = problem
        self.input_emb = Linear(dim_input_nodes, emb_size)
        if problem != 'kp':
            self.begin_end_tokens = Embedding(2, emb_size)
        self.nb_layers_encoder = nb_layers_encoder
        self.encoder = ModuleList([EncoderLayer(nb_heads, activation_attention, emb_size, dim_ff, activation_ff, dropout, batchnorm) for _ in range(nb_layers_encoder)])
        if problem == 'cvrp':
            output_dim = 2
        else:
            output_dim = 1
        self.scores_projection = Linear(emb_size, output_dim)

    def forward(self, inputs, **problem_data):
        if self.problem == 'op':
            assert 'dist_matrices' in problem_data
        input_emb = self.input_emb(inputs)
        if self.problem != 'kp':
            input_emb[:, 0, :] += self.begin_end_tokens(torch.tensor([[0]], device=inputs.device)).squeeze(1)
            input_emb[:, -1, :] += self.begin_end_tokens(torch.tensor([[1]], device=inputs.device)).squeeze(1)
        state = input_emb
        for layer in self.encoder:
            state = layer(state)
        scores = self.scores_projection(state).squeeze(-1)
        if self.problem == 'tsp':
            scores[:, 0] = scores[:, -1] = -np.inf
        elif self.problem == 'cvrp':
            scores[:, 0, :] = scores[:, -1, :] = -np.inf
            scores[..., 0][problem_data['demands'] > problem_data['remaining_capacities'].unsqueeze(-1)] = -np.inf
        elif self.problem == 'op':
            scores[:, 0] = scores[:, -1] = -np.inf
            scores[problem_data['dist_matrices'][:, 0] + problem_data['dist_matrices'][:, -1] - inputs[..., 3] > 1e-06] = -np.inf
        elif self.problem == 'kp':
            scores[problem_data['weights'] > problem_data['remaining_capacities'].unsqueeze(-1)] = -np.inf
        return scores.reshape(scores.shape[0], -1)

# Component: ResidualNorm
class ResidualNorm(nn.Module):

    def __init__(self, emb_size, dropout, batchnorm):
        super().__init__()
        self.batchnorm = batchnorm
        self.norm = BatchNorm1d(emb_size, track_running_stats=False) if batchnorm else None
        self.alpha = 1.0 if self.batchnorm else Parameter(torch.tensor(0.0))
        self.dropout = Dropout(dropout)

    def forward(self, state_before, modified_after):
        state_before = state_before + self.alpha * self.dropout(modified_after)
        if self.batchnorm:
            state_before = state_before.transpose(2, 1)
            state_before = self.norm(state_before)
            return state_before.transpose(2, 1)
        else:
            return state_before

# Component: EncoderLayer
class EncoderLayer(nn.Module):

    def __init__(self, nb_heads, activation_attention, emb_size, dim_ff, activation_ff, dropout, batchnorm):
        super(EncoderLayer, self).__init__()
        self.attn = MultiHeadAttention(emb_size, nb_heads, activation=activation_attention)
        self.linear1 = Linear(emb_size, dim_ff)
        self.linear2 = Linear(dim_ff, emb_size)
        assert activation_ff == 'relu' or activation_ff == 'gelu'
        if activation_ff == 'relu':
            self.activation = torch.nn.ReLU()
        else:
            self.activation = torch.nn.GELU()
        self.res_norm1 = ResidualNorm(emb_size, dropout, batchnorm)
        self.res_norm2 = ResidualNorm(emb_size, dropout, batchnorm)

    def forward(self, state):
        state_rc = state
        state = self.attn(state, state)
        state = self.res_norm1(state_rc, state)
        state_rc = state
        state = self.linear2(self.activation(self.linear1(state)))
        return self.res_norm2(state_rc, state)

# Component: MultiHeadAttention
class MultiHeadAttention(nn.Module):

    def __init__(self, dim, num_heads=8, use_biases=True, scale_dot_att=False, activation='softmax'):
        super().__init__()
        assert dim % num_heads == 0
        self.emb_size = dim
        self.scale_dot_att = scale_dot_att
        self.num_heads = num_heads
        self.head_dim = dim // num_heads
        assert activation == 'softmax' or activation == 'entmax'
        self.activation = activation
        self.lambda1 = nn.Parameter(torch.FloatTensor(num_heads, dim, self.head_dim))
        self.lambda2 = nn.Parameter(torch.FloatTensor(num_heads, dim, self.head_dim))
        self.theta1 = nn.Parameter(torch.FloatTensor(num_heads, dim, self.head_dim))
        self.theta2 = nn.Parameter(torch.FloatTensor(num_heads, dim, self.head_dim))
        self.bias_lambda = torch.nn.Parameter(torch.FloatTensor(num_heads, self.head_dim)) if use_biases else None
        self.bias_theta = torch.nn.Parameter(torch.FloatTensor(num_heads, self.head_dim)) if use_biases else None
        self._reset_params()

    def _reset_params(self):
        torch.nn.init.xavier_uniform_(self.lambda1)
        torch.nn.init.xavier_uniform_(self.lambda2)
        torch.nn.init.xavier_uniform_(self.theta1)
        torch.nn.init.xavier_uniform_(self.theta2)
        torch.nn.init.zeros_(self.bias_lambda)
        torch.nn.init.zeros_(self.bias_theta)

    def forward(self, x, y, mask=None):
        r = torch.einsum('bmp,kpd->bmkd', x, self.lambda1)
        if self.bias_lambda is not None:
            r = r + self.bias_lambda
        dot_att = torch.einsum('bmkd,kqd,bnq->kbmn', r, self.lambda2, y)
        if self.scale_dot_att:
            dot_att *= self.head_dim ** (-0.5)
        if mask is not None:
            if len(mask.shape) == 2:
                mask = mask.repeat(dot_att.shape[0], dot_att.shape[1], 1, 1)
            else:
                mask = mask.repeat(dot_att.shape[0], 1, 1, 1)
            dot_att[mask == 1] = -np.inf
        if self.activation == 'softmax':
            att_weights = torch.softmax(dot_att, dim=-2)
        else:
            att_weights = entmax.entmax15(dot_att, dim=-2)
        r = torch.einsum('kbmn,bmp,kpd->bnkd', att_weights, x, self.theta1)
        if self.bias_theta is not None:
            r = r + self.bias_theta
        output = torch.einsum('bnkd,kqd->bnq', r, self.theta2)
        return output

