# Component: GNNLayer
class GNNLayer(nn.Module):

    def __init__(self, hidden_dim, aggregation='sum', norm='batch', learn_norm=True, track_norm=False, gated=True):
        super(GNNLayer, self).__init__()
        self.hidden_dim = hidden_dim
        self.aggregation = aggregation
        self.norm = norm
        self.learn_norm = learn_norm
        self.track_norm = track_norm
        self.gated = gated
        assert self.gated, 'Use gating with GCN, pass the `--gated` flag'
        self.U = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.V = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.A = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.B = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.C = nn.Linear(hidden_dim, hidden_dim, bias=True)
        self.norm_h = {'layer': nn.LayerNorm(hidden_dim, elementwise_affine=learn_norm), 'batch': nn.BatchNorm1d(hidden_dim, affine=learn_norm, track_running_stats=track_norm)}.get(self.norm, None)
        self.norm_e = {'layer': nn.LayerNorm(hidden_dim, elementwise_affine=learn_norm), 'batch': nn.BatchNorm1d(hidden_dim, affine=learn_norm, track_running_stats=track_norm)}.get(self.norm, None)

    def forward(self, h, e, graph, mode='residual', edge_index=None, sparse=False):
        if not sparse:
            (batch_size, num_nodes, hidden_dim) = h.shape
        else:
            batch_size = None
            (num_nodes, hidden_dim) = h.shape
        h_in = h
        e_in = e
        Uh = self.U(h)
        if not sparse:
            Vh = self.V(h).unsqueeze(1).expand(-1, num_nodes, -1, -1)
        else:
            Vh = self.V(h[edge_index[1]])
        Ah = self.A(h)
        Bh = self.B(h)
        Ce = self.C(e)
        if not sparse:
            e = Ah.unsqueeze(1) + Bh.unsqueeze(2) + Ce
        else:
            e = Ah[edge_index[1]] + Bh[edge_index[0]] + Ce
        gates = torch.sigmoid(e)
        h = Uh + self.aggregate(Vh, graph, gates, edge_index=edge_index, sparse=sparse)
        if not sparse:
            h = self.norm_h(h.view(batch_size * num_nodes, hidden_dim)).view(batch_size, num_nodes, hidden_dim) if self.norm_h else h
        else:
            h = self.norm_h(h) if self.norm_h else h
        if not sparse:
            e = self.norm_e(e.view(batch_size * num_nodes * num_nodes, hidden_dim)).view(batch_size, num_nodes, num_nodes, hidden_dim) if self.norm_e else e
        else:
            e = self.norm_e(e) if self.norm_e else e
        h = F.relu(h)
        e = F.relu(e)
        if mode == 'residual':
            h = h_in + h
            e = e_in + e
        return (h, e)

    def aggregate(self, Vh, graph, gates, mode=None, edge_index=None, sparse=False):
        Vh = gates * Vh
        if not sparse:
            if (mode or self.aggregation) == 'mean':
                return torch.sum(Vh, dim=2) / torch.sum(graph, dim=2).unsqueeze(-1).type_as(Vh)
            elif (mode or self.aggregation) == 'max':
                return torch.max(Vh, dim=2)[0]
            else:
                return torch.sum(Vh, dim=2)
        else:
            sparseVh = SparseTensor(row=edge_index[0], col=edge_index[1], value=Vh, sparse_sizes=(graph.size(0), graph.size(1)))
            if (mode or self.aggregation) == 'mean':
                return sparse_mean(sparseVh, dim=1)
            elif (mode or self.aggregation) == 'max':
                return sparse_max(sparseVh, dim=1)
            else:
                return sparse_sum(sparseVh, dim=1)

# Component: PositionEmbeddingSine
class PositionEmbeddingSine(nn.Module):

    def __init__(self, num_pos_feats=64, temperature=10000, normalize=False, scale=None):
        super().__init__()
        self.num_pos_feats = num_pos_feats
        self.temperature = temperature
        self.normalize = normalize
        if scale is not None and normalize is False:
            raise ValueError('normalize should be True if scale is passed')
        if scale is None:
            scale = 2 * math.pi
        self.scale = scale

    def forward(self, x):
        y_embed = x[:, :, 0]
        x_embed = x[:, :, 1]
        if self.normalize:
            y_embed = y_embed * self.scale
            x_embed = x_embed * self.scale
        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)
        dim_t = self.temperature ** (2.0 * torch.div(dim_t, 2, rounding_mode='trunc') / self.num_pos_feats)
        pos_x = x_embed[:, :, None] / dim_t
        pos_y = y_embed[:, :, None] / dim_t
        pos_x = torch.stack((pos_x[:, :, 0::2].sin(), pos_x[:, :, 1::2].cos()), dim=3).flatten(2)
        pos_y = torch.stack((pos_y[:, :, 0::2].sin(), pos_y[:, :, 1::2].cos()), dim=3).flatten(2)
        pos = torch.cat((pos_y, pos_x), dim=2).contiguous()
        return pos

# Component: ScalarEmbeddingSine
class ScalarEmbeddingSine(nn.Module):

    def __init__(self, num_pos_feats=64, temperature=10000, normalize=False, scale=None):
        super().__init__()
        self.num_pos_feats = num_pos_feats
        self.temperature = temperature
        self.normalize = normalize
        if scale is not None and normalize is False:
            raise ValueError('normalize should be True if scale is passed')
        if scale is None:
            scale = 2 * math.pi
        self.scale = scale

    def forward(self, x):
        x_embed = x
        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)
        dim_t = self.temperature ** (2 * torch.div(dim_t, 2, rounding_mode='trunc') / self.num_pos_feats)
        pos_x = x_embed[:, :, :, None] / dim_t
        pos_x = torch.stack((pos_x[:, :, :, 0::2].sin(), pos_x[:, :, :, 1::2].cos()), dim=4).flatten(3)
        return pos_x

# Component: ScalarEmbeddingSine1D
class ScalarEmbeddingSine1D(nn.Module):

    def __init__(self, num_pos_feats=64, temperature=10000, normalize=False, scale=None):
        super().__init__()
        self.num_pos_feats = num_pos_feats
        self.temperature = temperature
        self.normalize = normalize
        if scale is not None and normalize is False:
            raise ValueError('normalize should be True if scale is passed')
        if scale is None:
            scale = 2 * math.pi
        self.scale = scale

    def forward(self, x):
        x_embed = x
        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)
        dim_t = self.temperature ** (2 * torch.div(dim_t, 2, rounding_mode='trunc') / self.num_pos_feats)
        pos_x = x_embed[:, None] / dim_t
        pos_x = torch.stack((pos_x[:, 0::2].sin(), pos_x[:, 1::2].cos()), dim=2).flatten(1)
        return pos_x

# Component: run_sparse_layer
def run_sparse_layer(layer, time_layer, out_layer, adj_matrix, edge_index, add_time_on_edge=True):

    def custom_forward(*inputs):
        x_in = inputs[0]
        e_in = inputs[1]
        time_emb = inputs[2]
        (x, e) = layer(x_in, e_in, adj_matrix, mode='direct', edge_index=edge_index, sparse=True)
        if add_time_on_edge:
            e = e + time_layer(time_emb)
        else:
            x = x + time_layer(time_emb)
        x = x_in + x
        e = e_in + out_layer(e)
        return (x, e)
    return custom_forward

# Component: GNNEncoder
class GNNEncoder(nn.Module):

    def __init__(self, n_layers, hidden_dim, out_channels=1, aggregation='sum', norm='layer', learn_norm=True, track_norm=False, gated=True, sparse=False, use_activation_checkpoint=False, node_feature_only=False):
        super(GNNEncoder, self).__init__()
        self.sparse = sparse
        self.node_feature_only = node_feature_only
        self.hidden_dim = hidden_dim
        time_embed_dim = hidden_dim // 2
        self.node_embed = nn.Linear(hidden_dim, hidden_dim)
        self.edge_embed = nn.Linear(hidden_dim, hidden_dim)
        if not node_feature_only:
            self.pos_embed = PositionEmbeddingSine(hidden_dim // 2, normalize=True)
            self.edge_pos_embed = ScalarEmbeddingSine(hidden_dim, normalize=False)
        else:
            self.pos_embed = ScalarEmbeddingSine1D(hidden_dim, normalize=False)
        self.time_embed = nn.Sequential(nn.Linear(hidden_dim, time_embed_dim), nn.ReLU(), nn.Linear(time_embed_dim, time_embed_dim))
        self.out = nn.Sequential(normalize(hidden_dim), nn.ReLU(), nn.Conv2d(hidden_dim, out_channels, kernel_size=1, bias=True))
        self.layers = nn.ModuleList([GNNLayer(hidden_dim, aggregation, norm, learn_norm, track_norm, gated) for _ in range(n_layers)])
        self.time_embed_layers = nn.ModuleList([nn.Sequential(nn.ReLU(), nn.Linear(time_embed_dim, hidden_dim)) for _ in range(n_layers)])
        self.per_layer_out = nn.ModuleList([nn.Sequential(nn.LayerNorm(hidden_dim, elementwise_affine=learn_norm), nn.SiLU(), zero_module(nn.Linear(hidden_dim, hidden_dim))) for _ in range(n_layers)])
        self.use_activation_checkpoint = use_activation_checkpoint

    def dense_forward(self, x, graph, timesteps, edge_index=None):
        del edge_index
        x = self.node_embed(self.pos_embed(x))
        e = self.edge_embed(self.edge_pos_embed(graph))
        time_emb = self.time_embed(positional_encoding_DIFUSCO(timesteps, self.hidden_dim, 10000, 1))
        graph = torch.ones_like(graph).long()
        for (layer, time_layer, out_layer) in zip(self.layers, self.time_embed_layers, self.per_layer_out):
            (x_in, e_in) = (x, e)
            if self.use_activation_checkpoint:
                raise NotImplementedError
            (x, e) = layer(x, e, graph, mode='direct')
            if not self.node_feature_only:
                e = e + time_layer(time_emb)[:, None, None, :]
            else:
                x = x + time_layer(time_emb)[:, None, :]
            x = x_in + x
            e = e_in + out_layer(e)
        e = self.out(e.permute((0, 3, 1, 2)))
        return e

    def sparse_forward(self, x, graph, timesteps, edge_index):
        x = self.node_embed(self.pos_embed(x.unsqueeze(0)).squeeze(0))
        e = self.edge_embed(self.edge_pos_embed(graph.expand(1, 1, -1)).squeeze())
        time_emb = self.time_embed(positional_encoding_DIFUSCO(timesteps, self.hidden_dim, 10000, 1))
        edge_index = edge_index.long()
        (x, e) = self.sparse_encoding(x, e, edge_index, time_emb)
        e = e.reshape((1, x.shape[0], -1, e.shape[-1])).permute((0, 3, 1, 2))
        e = self.out(e).reshape(-1, edge_index.shape[1]).permute((1, 0))
        return e

    def sparse_forward_node_feature_only(self, x, timesteps, edge_index):
        x = self.node_embed(self.pos_embed(x))
        x_shape = x.shape
        e = torch.zeros(edge_index.size(1), self.hidden_dim, device=x.device)
        time_emb = self.time_embed(positional_encoding_DIFUSCO(timesteps, self.hidden_dim, 10000, 1))
        edge_index = edge_index.long()
        (x, e) = self.sparse_encoding(x, e, edge_index, time_emb)
        x = x.reshape((1, x_shape[0], -1, x.shape[-1])).permute((0, 3, 1, 2))
        x = self.out(x).reshape(-1, x_shape[0]).permute((1, 0))
        return x

    def sparse_encoding(self, x, e, edge_index, time_emb):
        adj_matrix = SparseTensor(row=edge_index[0], col=edge_index[1], value=torch.ones_like(edge_index[0].float()), sparse_sizes=(x.shape[0], x.shape[0]))
        adj_matrix = adj_matrix.to(x.device)
        for (layer, time_layer, out_layer) in zip(self.layers, self.time_embed_layers, self.per_layer_out):
            (x_in, e_in) = (x, e)
            if self.use_activation_checkpoint:
                single_time_emb = time_emb[:1]
                run_sparse_layer_fn = functools.partial(run_sparse_layer, add_time_on_edge=not self.node_feature_only)
                out = activation_checkpoint.checkpoint(run_sparse_layer_fn(layer, time_layer, out_layer, adj_matrix, edge_index), x_in, e_in, single_time_emb)
                x = out[0]
                e = out[1]
            else:
                (x, e) = layer(x_in, e_in, adj_matrix, mode='direct', edge_index=edge_index, sparse=True)
                if not self.node_feature_only:
                    e = e + time_layer(time_emb)
                else:
                    x = x + time_layer(time_emb)
                x = x_in + x
                e = e_in + out_layer(e)
        return (x, e)

    def forward(self, x, timesteps, graph=None, edge_index=None):
        if self.node_feature_only:
            if self.sparse:
                return self.sparse_forward_node_feature_only(x, timesteps, edge_index)
            else:
                raise NotImplementedError
        elif self.sparse:
            return self.sparse_forward(x, graph, timesteps, edge_index)
        else:
            return self.dense_forward(x, graph, timesteps, edge_index)

# Component: normalize
def normalize(x):
    return nn.GroupNorm(32, x)

# Component: zero_module
def zero_module(module):
    for p in module.parameters():
        p.detach().zero_()
    return module

# Component: TSPDiffusionPolicy.__init__
def __init__(self, env_name, n_layers, hidden_dim, aggregation, diffusion_type, diffusion_schedule, diffusion_steps, sparse_factor, use_activation_checkpoint, parallel_sampling, sequential_sampling, inference_diffusion_steps, inference_schedule, inference_trick, node_feature_only=False):
    super().__init__()
    self.problem_type = env_name
    self.diffusion_type = diffusion_type
    self.diffusion_schedule = diffusion_schedule
    self.diffusion_steps = diffusion_steps
    self.sparse = sparse_factor > 0 or node_feature_only
    self.sparse_factor = sparse_factor
    self.parallel_sampling = parallel_sampling
    self.sequential_sampling = sequential_sampling
    self.inference_diffusion_steps = inference_diffusion_steps
    self.inference_schedule = inference_schedule
    self.inference_trick = inference_trick
    if self.diffusion_type == 'gaussian':
        out_channels = 1
        self.diffusion = GaussianDiffusion(T=self.diffusion_steps, schedule=self.diffusion_schedule)
    elif self.diffusion_type == 'categorical':
        out_channels = 2
        self.diffusion = CategoricalDiffusion(T=self.diffusion_steps, schedule=self.diffusion_schedule, sparse=self.sparse)
    else:
        raise ValueError(f'Unknown diffusion type {self.diffusion_type}')
    self.model = GNNEncoder(n_layers=n_layers, hidden_dim=hidden_dim, out_channels=out_channels, aggregation=aggregation, sparse=self.sparse, use_activation_checkpoint=use_activation_checkpoint, node_feature_only=node_feature_only)
    self.num_training_steps_cached = None

# Component: TSPDiffusionPolicy.forward
def forward(self, x, adj, t, edge_index):
    return self.model(x, t, adj, edge_index)

