# Component: _tsp_get_parameters
def _tsp_get_parameters(cities: FloatPointArray, order: Optional[IntegerArray]=None, batched=False, euclidean=True) -> Tuple[Tuple[Float32Array, UInt32Array, bool], UInt32Array]:
    if batched:
        assert len(cities.shape) == 3
        (batch_size, citycount, n) = cities.shape
        out = np.zeros((batch_size, citycount), dtype=np.uint32)
    else:
        assert len(cities.shape) == 2
        (citycount, n) = cities.shape
        out = np.zeros(citycount, dtype=np.uint32)
    assert n == 2 if euclidean else n == citycount
    if order is None:
        order = np.arange(citycount, dtype=np.uint32)
    elif batched and len(order.shape) == 2:
        assert tuple(order.shape) == (batch_size, citycount)
    else:
        assert len(order.shape) == 1 and order.shape[0] == citycount
    _order = np.ascontiguousarray(order, dtype=np.uint32)
    _cities = np.ascontiguousarray(cities, dtype=np.float32)
    return ((_cities, _order, euclidean), out)

Solver implementation role: encoder

# Component: LEHDEncoder
class LEHDEncoder(nn.Module):

    def __init__(self, problem_type: str='tsp', node_dim: int=2, embed_dim: int=128, num_heads: int=8, qkv_dim: int=16, feedforward_hidden: int=512, normalization: str=None, bias: bool=False):
        super().__init__()
        if problem_type == 'tsp':
            self.embedding = nn.Linear(node_dim, embed_dim, bias=True, dtype=torch.float32)
        elif problem_type == 'cvrp':
            self.embedding = nn.Linear(node_dim + 1, embed_dim, bias=True, dtype=torch.float32)
        self.MHA_embed = TransformerNet(1, num_heads, qkv_dim, embed_dim, normalization, feedforward_hidden, bias)

    def forward(self, data):
        embed_data = self.MHA_embed(self.embedding(data))
        return embed_data

