# Component: MatNetInitialization
class MatNetInitialization(ARInitialization):

    def __init__(self, policy: nn.Module):
        super().__init__(policy.model)

    def run(self, env: EnvBase, batch: int, strategy: str, phase: Literal['train', 'eval'], **kwargs) -> Tuple[TensorDict, Any]:
        pomo_size = kwargs.get('pomo_size')
        if pomo_size == 24:
            env.pomo_size = 24
        return super().run(env, batch, strategy, phase, **kwargs)

# Component: ARInitialization.run
def run(self, env: EnvBase, batch: Union[Tensor, dict, list], strategy: str, phase: Literal['train', 'eval'], **kwargs) -> Tuple[TensorDict, Any]:
