    if self.method_name == 'matpoenet':
        return TensorDict({'ninf_mask': self.ninf_mask, 'batch_idx': self.BATCH_IDX, 'pomo_idx': self.POMO_IDX, 'current_node': self.dummy_flag_long, 'reward': self.dummy_flag_long, 'done': self.dummy_flag_bool, 'pos_emb': self.pos_emb}, batch_size=self.batch_size)
    else:
        return TensorDict({'ninf_mask': self.ninf_mask, 'batch_idx': self.BATCH_IDX, 'pomo_idx': self.POMO_IDX, 'current_node': self.dummy_flag_long, 'reward': self.dummy_flag_long, 'done': self.dummy_flag_bool}, batch_size=self.batch_size)

# Component: ATSPEnv._step
def _step(self, td: TensorDict) -> TensorDict:
    self.selected_count += 1
    self.current_node = td['action']
    self.selected_node_list = torch.cat((self.selected_node_list, self.current_node[:, :, None]), dim=2)
    ninf_mask = td['ninf_mask']
    ninf_mask[self.BATCH_IDX, self.POMO_IDX, self.current_node] = float('-inf')
    done = self.selected_count == self.node_cnt
    if done.all():
        reward = -self._get_total_distance()
    else:
        reward = self.dummy_flag_long
    next_state = {'ninf_mask': self.ninf_mask, 'selected_count': self.selected_count, 'selected_node_list': self.selected_node_list, 'reward': reward, 'done': done}
    return TensorDict({'next': next_state, 'ninf_mask': ninf_mask, 'batch_idx': self.BATCH_IDX, 'pomo_idx': self.POMO_IDX, 'reward': reward, 'done': done, 'current_node': self.current_node}, batch_size=self.batch_size)

# Component: ATSPEnv._get_total_distance
def _get_total_distance(self):
    node_from = self.selected_node_list
    node_to = self.selected_node_list.roll(dims=2, shifts=-1)
    batch_index = self.BATCH_IDX[:, :, None].expand(self.env_batch_size, self.pomo_size, self.node_cnt)
    selected_cost = self.problems[batch_index, node_from, node_to]
    total_distance = selected_cost.sum(2)
    return total_distance

