Solver implementation role: encoder

# Component: MTMoEEncoder
class MTMoEEncoder(nn.Module):

    def __init__(self, embedding_dim, ff_hidden_dim, encoder_layer_num, head_num=8, qkv_dim=16, normalization='batch', norm_loc='norm_last', MoE_param=None):
        super().__init__()
        self.MoE_param = MoE_param
        if MoE_param['num_experts'] > 1 and 'Raw' in MoE_param['expert_loc']:
            self.embedding_depot = MoE(input_size=2, output_size=embedding_dim, num_experts=MoE_param['num_experts'], k=MoE_param['topk'], T=1.0, noisy_gating=True, routing_level=MoE_param['routing_level'], routing_method=MoE_param['routing_method'], moe_model='Linear')
            self.embedding_node = MoE(input_size=5, output_size=embedding_dim, num_experts=MoE_param['num_experts'], k=MoE_param['topk'], T=1.0, noisy_gating=True, routing_level=MoE_param['routing_level'], routing_method=MoE_param['routing_method'], moe_model='Linear')
        else:
            self.embedding_depot = nn.Linear(2, embedding_dim)
            self.embedding_node = nn.Linear(5, embedding_dim)
        self.layers = nn.ModuleList([EncoderLayer(i, embedding_dim, ff_hidden_dim, head_num, qkv_dim, normalization, norm_loc, MoE_param) for i in range(encoder_layer_num)])

    def forward(self, depot_xy, node_xy_demand_tw):
        moe_loss = 0
        if isinstance(self.embedding_depot, MoE) or isinstance(self.embedding_node, MoE):
            (embedded_depot, loss_depot) = self.embedding_depot(depot_xy)
            (embedded_node, loss_node) = self.embedding_node(node_xy_demand_tw)
            moe_loss = moe_loss + loss_depot + loss_node
        else:
            embedded_depot = self.embedding_depot(depot_xy)
            embedded_node = self.embedding_node(node_xy_demand_tw)
        out = torch.cat((embedded_depot, embedded_node), dim=1)
        for layer in self.layers:
            (out, loss) = layer(out)
            moe_loss = moe_loss + loss
        return (out, moe_loss)

# Component: EncoderLayer
class EncoderLayer(nn.Module):

    def __init__(self, depth=0, embedding_dim=128, ff_hidden_dim=512, head_num=8, qkv_dim=16, normalization='batch', norm_loc='norm_last', MoE_param=None):
        super().__init__()
        self.head_num = head_num
        self.norm_loc = norm_loc
        self.Wq = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.Wk = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.Wv = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.multi_head_combine = nn.Linear(head_num * qkv_dim, embedding_dim)
        self.addAndNormalization1 = Add_And_Normalization_Module(embedding_dim, norm=normalization, norm_loc=norm_loc)
        if MoE_param['num_experts'] > 1 and 'Enc{}'.format(depth) in MoE_param['expert_loc']:
            self.feedForward = MoE(input_size=embedding_dim, output_size=embedding_dim, num_experts=MoE_param['num_experts'], hidden_size=ff_hidden_dim, k=MoE_param['topk'], T=1.0, noisy_gating=True, routing_level=MoE_param['routing_level'], routing_method=MoE_param['routing_method'], moe_model='MLP')
        else:
            self.feedForward = FeedForward(embedding_dim, ff_hidden_dim)
        self.addAndNormalization2 = Add_And_Normalization_Module(embedding_dim, norm=normalization, norm_loc=norm_loc)

    def forward(self, input1):
        (head_num, moe_loss) = (self.head_num, 0)
        q = reshape_by_heads(self.Wq(input1), head_num=head_num)
        k = reshape_by_heads(self.Wk(input1), head_num=head_num)
        v = reshape_by_heads(self.Wv(input1), head_num=head_num)
        if self.norm_loc == 'norm_last':
            out_concat = multi_head_attention(q, k, v)
            multi_head_out = self.multi_head_combine(out_concat)
            out1 = self.addAndNormalization1(input1, multi_head_out)
            (out2, moe_loss) = self.feedForward(out1)
            out3 = self.addAndNormalization2(out1, out2)
        else:
            out1 = self.addAndNormalization1(None, input1)
            multi_head_out = self.multi_head_combine(out1)
            input2 = input1 + multi_head_out
            out2 = self.addAndNormalization2(None, input2)
            (out2, moe_loss) = self.feedForward(out2)
            out3 = input2 + out2
        return (out3, moe_loss)

# Component: Add_And_Normalization_Module
class Add_And_Normalization_Module(nn.Module):

    def __init__(self, embedding_dim=128, norm='batch', norm_loc='norm_last'):
        super().__init__()
        self.add = True if norm_loc == 'norm_last' else False
        if norm == 'batch':
            self.norm = nn.BatchNorm1d(embedding_dim, affine=True, track_running_stats=True)
        elif norm == 'batch_no_track':
            self.norm = nn.BatchNorm1d(embedding_dim, affine=True, track_running_stats=False)
        elif norm == 'instance':
            self.norm = nn.InstanceNorm1d(embedding_dim, affine=True, track_running_stats=False)
        elif norm == 'layer':
            self.norm = nn.LayerNorm(embedding_dim)
        elif norm == 'rezero':
            self.norm = torch.nn.Parameter(torch.Tensor([0.0]), requires_grad=True)
        else:
            self.norm = None

    def forward(self, input1=None, input2=None):
        if isinstance(self.norm, nn.InstanceNorm1d):
            added = input1 + input2 if self.add else input2
            transposed = added.transpose(1, 2)
            normalized = self.norm(transposed)
            back_trans = normalized.transpose(1, 2)
        elif isinstance(self.norm, nn.BatchNorm1d):
            added = input1 + input2 if self.add else input2
            (batch, problem, embedding) = added.size()
            normalized = self.norm(added.reshape(batch * problem, embedding))
            back_trans = normalized.reshape(batch, problem, embedding)
        elif isinstance(self.norm, nn.LayerNorm):
            added = input1 + input2 if self.add else input2
            back_trans = self.norm(added)
        elif isinstance(self.norm, nn.Parameter):
            back_trans = input1 + self.norm * input2 if self.add else self.norm * input2
        else:
            back_trans = input1 + input2 if self.add else input2
        return back_trans

# Component: SparseDispatcher
class SparseDispatcher(object):

    def __init__(self, num_experts, gates, routing_level='node'):
        self._gates = gates
        self._num_experts = num_experts
        self._routing_level = routing_level
        (sorted_experts, index_sorted_experts) = torch.nonzero(gates).sort(0)
        (_, self._expert_index) = sorted_experts.split(1, dim=1)
        self._batch_index = torch.nonzero(gates)[index_sorted_experts[:, 1], 0]
        self._part_sizes = (gates > 0).sum(0).tolist()
        gates_exp = gates[self._batch_index.flatten()]
        self._nonzero_gates = torch.gather(gates_exp, 1, self._expert_index)

    def dispatch(self, inp):
        inp_exp = inp[self._batch_index].squeeze(1)
        return torch.split(inp_exp, self._part_sizes, dim=0)

    def combine(self, expert_out, multiply_by_gates=True):
        stitched = torch.cat(expert_out, 0)
        if multiply_by_gates:
            if self._routing_level == 'node':
                stitched = stitched.mul(self._nonzero_gates)
            elif self._routing_level == 'instance':
                stitched = stitched.mul(self._nonzero_gates.unsqueeze(1))
        if self._routing_level == 'node':
            zeros = torch.zeros(self._gates.size(0), expert_out[-1].size(-1), requires_grad=True, device=stitched.device)
        elif self._routing_level == 'instance':
            zeros = torch.zeros(self._gates.size(0), expert_out[-1].size(1), expert_out[-1].size(-1), requires_grad=True, device=stitched.device)
        combined = zeros.index_add(0, self._batch_index, stitched.float())
        combined[combined == 0] = np.finfo(float).eps
        return combined

    def expert_to_gates(self):
        return torch.split(self._nonzero_gates, self._part_sizes, dim=0)

# Component: MLP
class MLP(nn.Module):

    def __init__(self, input_size=128, output_size=128, hidden_size=512):
        super(MLP, self).__init__()
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.fc2 = nn.Linear(hidden_size, output_size)
        self.relu = nn.ReLU()

    def forward(self, x):
        return self.fc2(self.relu(self.fc1(x)))

# Component: MoE
class MoE(nn.Module):

    def __init__(self, input_size, output_size, num_experts, hidden_size=None, k=1, T=1.0, noisy_gating=True, routing_level='node', routing_method='input_choice', moe_model='MLP'):
        super(MoE, self).__init__()
        self.noisy_gating = noisy_gating
        self.routing_level = routing_level
        self.routing_method = routing_method
        self.num_experts = num_experts
        self.output_size = output_size
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.k = k
        self.T = T
        if moe_model == 'MLP':
            self.experts = nn.ModuleList([MLP(self.input_size, self.output_size, self.hidden_size) for _ in range(self.num_experts)])
        elif moe_model == 'Linear':
            self.experts = nn.ModuleList([nn.Linear(self.input_size, self.output_size) for _ in range(self.num_experts)])
        else:
            raise NotImplementedError
        if routing_method == 'soft_moe':
            self.w_gate = nn.Parameter(torch.zeros(input_size, num_experts * k), requires_grad=True)
        else:
            self.w_gate = nn.Parameter(torch.zeros(input_size, num_experts), requires_grad=True)
        self.w_noise = nn.Parameter(torch.zeros(input_size, num_experts), requires_grad=True)
        if not (routing_level in ['node', 'instance'] and routing_method == 'input_choice'):
            torch.nn.init.kaiming_uniform_(self.w_gate, a=math.sqrt(5))
        self.softplus = nn.Softplus()
        self.softmax = nn.Softmax(-1)
        self.register_buffer('mean', torch.tensor([0.0]))
        self.register_buffer('std', torch.tensor([1.0]))
        assert self.k <= self.num_experts

    def cv_squared(self, x):
        eps = 1e-10
        if x.shape[0] == 1:
            return torch.tensor([0], device=x.device, dtype=x.dtype)
        return x.float().var() / (x.float().mean() ** 2 + eps)

    def _gates_to_load(self, gates):
        return (gates > 0).sum(0)

    def _prob_in_top_k(self, clean_values, noisy_values, noise_stddev, noisy_top_values):
        batch = clean_values.size(0)
        m = noisy_top_values.size(1)
        top_values_flat = noisy_top_values.flatten()
        threshold_positions_if_in = torch.arange(batch, device=clean_values.device) * m + self.k
        threshold_if_in = torch.unsqueeze(torch.gather(top_values_flat, 0, threshold_positions_if_in), 1)
        is_in = torch.gt(noisy_values, threshold_if_in)
        threshold_positions_if_out = threshold_positions_if_in - 1
        threshold_if_out = torch.unsqueeze(torch.gather(top_values_flat, 0, threshold_positions_if_out), 1)
        normal = Normal(self.mean, self.std)
        prob_if_in = normal.cdf((clean_values - threshold_if_in) / noise_stddev)
        prob_if_out = normal.cdf((clean_values - threshold_if_out) / noise_stddev)
        prob = torch.where(is_in, prob_if_in, prob_if_out)
        return prob

    def noisy_top_k_gating(self, x, train, noise_epsilon=0.01):
        x = x.mean(1) if self.routing_level == 'instance' else x
        clean_logits = x @ self.w_gate
        if self.noisy_gating and train:
            raw_noise_stddev = x @ self.w_noise
            noise_stddev = self.softplus(raw_noise_stddev) + noise_epsilon
            noisy_logits = clean_logits + torch.randn_like(clean_logits) * noise_stddev
            logits = noisy_logits
        else:
            logits = clean_logits
        (top_logits, top_indices) = logits.topk(min(self.k + 1, self.num_experts), dim=-1)
        top_k_logits = top_logits[..., :self.k]
        top_k_indices = top_indices[..., :self.k]
        top_k_gates = self.softmax(top_k_logits / self.T)
        zeros = torch.zeros_like(logits, requires_grad=True)
        gates = zeros.scatter(-1, top_k_indices, top_k_gates)
        if self.noisy_gating and self.k < self.num_experts and train:
            load = self._prob_in_top_k(clean_logits, noisy_logits, noise_stddev, top_logits).sum(0)
        else:
            load = self._gates_to_load(gates)
        return (gates, load)

    def problem_top_k_gating(self, x, prob_emb=None):
        x = x.mean(0).mean(0).unsqueeze(0) + prob_emb if prob_emb is not None else x.mean(0).mean(0).unsqueeze(0)
        logits = x @ self.w_gate
        (top_logits, top_indices) = logits.topk(min(self.k + 1, self.num_experts), dim=-1)
        selected_logits = top_logits[..., :self.k].squeeze(0)
        selected_indices = top_indices[..., :self.k].squeeze(0)
        selected_gates = self.softmax(selected_logits / self.T)
        return (selected_indices, selected_gates)

    def expert_gating(self, x, k):
        x = x.mean(1) if self.routing_level == 'instance' else x
        logits = x @ self.w_gate
        S = torch.softmax(logits, dim=0)
        (G, I) = torch.topk(S.T, k=k, dim=-1)
        P = nn.functional.one_hot(I, num_classes=x.size(0))
        return (G, I, P)

    def forward(self, x, loss_coef=0.001, prob_emb=None):
        assert self.routing_level in ['node', 'instance', 'problem'], 'Unsupported Routing Level!'
        output_shape = list(x.size()[:-1]) + [self.output_size]
        if self.routing_level in ['instance', 'problem']:
            assert x.dim() == 3
        elif self.routing_level == 'node':
            x = x.reshape(-1, self.input_size) if x.dim() != 2 else x
        if self.routing_level == 'problem':
            if self.routing_method != 'random':
                (expert_ids, gates) = self.problem_top_k_gating(x, prob_emb)
            else:
                expert_ids = torch.randperm(self.num_experts)[:self.k]
                gates = torch.Tensor([1.0 / self.k for _ in range(self.k)])
            expert_outputs = []
            for i in expert_ids.tolist():
                expert_outputs.append(self.experts[i](x).unsqueeze(0))
            expert_outputs = torch.cat(expert_outputs, 0)
            y = (expert_outputs * gates.reshape(-1, 1, 1, 1)).sum(0)
            return (y, 0)
        elif self.routing_level in ['node', 'instance']:
            if self.routing_method == 'input_choice':
                (gates, load) = self.noisy_top_k_gating(x, self.training)
                importance = gates.sum(0)
                loss = self.cv_squared(importance) + self.cv_squared(load)
                loss *= loss_coef
                dispatcher = SparseDispatcher(self.num_experts, gates, routing_level=self.routing_level)
                expert_inputs = dispatcher.dispatch(x)
                expert_outputs = [self.experts[i](expert_inputs[i]) for i in range(self.num_experts)]
                y = dispatcher.combine(expert_outputs)
                return (y.reshape(output_shape), loss)
            elif self.routing_method == 'expert_choice':
                assert self.input_size == self.output_size
                k = int(x.size(0) * self.k / self.num_experts)
                expert_inputs_shape = [self.num_experts, k] + list(x.size()[1:])
                (G, I, P) = self.expert_gating(x, k)
                expert_inputs = P.float() @ x.reshape(P.size(-1), -1)
                expert_inputs = expert_inputs.reshape(expert_inputs_shape)
                expert_outputs = [self.experts[i](expert_inputs[i]) for i in range(self.num_experts)]
                expert_outputs = torch.stack(expert_outputs, 0)
                output = torch.einsum('ijl,ij,ijd->ld', P, G, expert_outputs.reshape(self.num_experts, k, -1))
                return (output.reshape(output_shape), 0)
            elif self.routing_method == 'soft_moe':
                x_ = x.mean(1) if self.routing_level == 'instance' else x
                logits = x_ @ self.w_gate
                expert_inputs_shape = [logits.size(-1)] + list(x.size()[1:])
                expert_inputs = torch.softmax(logits, dim=0).T @ x.reshape(logits.size(0), -1)
                expert_inputs = expert_inputs.reshape(expert_inputs_shape)
                expert_outputs = [self.experts[i](expert_inputs[i * self.k:(i + 1) * self.k]) for i in range(self.num_experts)]
                expert_outputs = torch.stack(expert_outputs, 0).reshape(self.num_experts * self.k, -1)
                output = torch.softmax(logits, dim=-1) @ expert_outputs
                return (output.reshape(output_shape), 0)
            elif self.routing_method == 'random':
                zeros = torch.zeros((x.size(0), self.num_experts), requires_grad=True)
                random_indices = torch.argsort(torch.rand(x.size(0), self.num_experts), dim=-1)[:, :self.k]
                gates = zeros.scatter(-1, random_indices, 1.0 / self.k)
                dispatcher = SparseDispatcher(self.num_experts, gates, routing_level=self.routing_level)
                expert_inputs = dispatcher.dispatch(x)
                expert_outputs = [self.experts[i](expert_inputs[i]) for i in range(self.num_experts)]
                y = dispatcher.combine(expert_outputs)
                return (y.reshape(output_shape), 0)
            else:
                raise NotImplementedError

Solver implementation role: encoder

# Component: CadaEncoder
class CadaEncoder(nn.Module):

    def __init__(self, init_embedding: nn.Module=None, prompt_embedding: nn.Module=None, num_heads: int=8, embed_dim: int=128, num_layers: int=6, feedforward_hidden: int=512, normalization: str='rms', use_prenorm: bool=False, use_post_layers_norm: bool=False, parallel_gated_kwargs: dict=None, attn_sparse_ratio: float=0.5, sparse_applied_to_score: bool=None, **transformer_kwargs):
        super(CadaEncoder, self).__init__()
        self.num_layers = num_layers
        if init_embedding is None:
            init_embedding = MTVRPInitEmbeddingRouteFinder(embed_dim=embed_dim)
        else:
            log.warning('Using custom init_embedding')
        self.init_embedding = init_embedding
        if prompt_embedding is None:
            prompt_embedding = MTVRPPromptEmbedding(embed_dim=embed_dim, normalization=None)
        else:
            log.warning('Using custom prompt_embedding')
        self.prompt_embedding = prompt_embedding
        self.global_layers = nn.Sequential(*(TransformerBlock(embed_dim=embed_dim, num_heads=num_heads, feedforward_hidden=feedforward_hidden, normalization=normalization, use_prenorm=use_prenorm, parallel_gated_kwargs=parallel_gated_kwargs, attn_sparse_ratio=1.0, **transformer_kwargs) for _ in range(num_layers)))
        self.sparse_layers = nn.Sequential(*(TransformerBlock(embed_dim=embed_dim, num_heads=num_heads, feedforward_hidden=feedforward_hidden, normalization=normalization, use_prenorm=use_prenorm, parallel_gated_kwargs=parallel_gated_kwargs, attn_sparse_ratio=attn_sparse_ratio, sparse_applied_to_score=sparse_applied_to_score, **transformer_kwargs) for _ in range(num_layers)))
        self.global_linears = nn.Sequential(*(nn.Linear(embed_dim, embed_dim, bias=True) for _ in range(num_layers)))
        self.sparse_linears = nn.Sequential(*(nn.Linear(embed_dim, embed_dim, bias=True) for _ in range(num_layers)))
        self.post_layers_norm = Normalization(embed_dim, normalization) if use_post_layers_norm else None

    def forward(self, td: Tensor, mask: Union[Tensor, None]=None) -> Tuple[Tensor, Tensor]:
        (has_open, has_tw, has_limit, has_backhaul, backhaul_class) = MTVRPEnv.check_variants(td)
        prompt = torch.stack((has_open, has_tw, has_limit, has_backhaul), dim=-1).to(torch.float32)
        init_h = self.init_embedding(td)
        init_h = self.prompt_embedding(prompt, init_h)
        hg = init_h
        hs = init_h
        for i in range(self.num_layers):
            hg_layer = self.global_layers[i]
            hs_layer = self.sparse_layers[i]
            hg_linear = self.global_linears[i]
            hs_linear = self.sparse_linears[i]
            _hg = hg_layer(hg, mask)
            _hs = hs_layer(hs, mask)
            hg = _hg + hg_linear(_hs)
            hs = _hs + hs_linear(_hg)
        if self.post_layers_norm is not None:
            hg = self.post_layers_norm(hg)
        return (hg, init_h)

# Component: CadaLoRAEncoder
class CadaLoRAEncoder(nn.Module):

    def __init__(self, encoder: CadaEncoder=None, lora_rank: int=32, lora_alpha: float=0.5, lora_use_gate: bool=True, lora_act_func: str='sigmoid', lora_use_linear: bool=False, lora_init_embed: bool=True, lora_prompt_embed: bool=True, lora_query: bool=True, lora_key: bool=True, lora_value: bool=True, lora_projection: bool=True, lora_ffn: bool=True, lora_fusion: bool=True, lora_norm: bool=True, assign_lora: Callable=None):
        super(CadaLoRAEncoder, self).__init__()
        if assign_lora == None:
            assign_lora = partial(LinearWithLoRA, rank=lora_rank, alpha=lora_alpha, use_gate=lora_use_gate, act_func=lora_act_func, use_linear=lora_use_linear)
        self.lora_init_embed = lora_init_embed
        self.lora_prompt_embed = lora_prompt_embed
        self.lora_query = lora_query
        self.lora_key = lora_key
        self.lora_value = lora_value
        self.lora_projection = lora_projection
        self.lora_ffn = lora_ffn
        self.lora_fusion = lora_fusion
        self.lora_norm = lora_norm
        self.encoder = self.assign_lora_layers(encoder, assign_lora)

    def assign_lora_layers(self, encoder: CadaEncoder, assign_lora):
        assert isinstance(encoder.init_embedding, MTVRPInitEmbeddingRouteFinder)
        assert isinstance(encoder.prompt_embedding, MTVRPPromptEmbedding)
        if self.lora_init_embed:
            encoder.init_embedding.project_global_feats = assign_lora(encoder.init_embedding.project_global_feats)
            encoder.init_embedding.project_customers_feats = assign_lora(encoder.init_embedding.project_customers_feats)
        if self.lora_prompt_embed:
            encoder.prompt_embedding.prompt_l1 = assign_lora(encoder.prompt_embedding.prompt_l1)
            encoder.prompt_embedding.prompt_l2 = assign_lora(encoder.prompt_embedding.prompt_l2)
            encoder.prompt_embedding.prompt_l3 = assign_lora(encoder.prompt_embedding.prompt_l3)

        def assign_transformer(layers):
            for layer in layers:
                if self.lora_query:
                    layer.attention.Wq = assign_lora(layer.attention.Wq)
                if self.lora_key:
                    layer.attention.Wk = assign_lora(layer.attention.Wk)
                if self.lora_value:
                    layer.attention.Wv = assign_lora(layer.attention.Wv)
                if self.lora_projection:
                    layer.attention.out_proj = assign_lora(layer.attention.out_proj)
                if self.lora_ffn:
                    if isinstance(layer.ffn, MLP):
                        for ffn_lin in layer.ffn.lins:
                            ffn_lin = assign_lora(ffn_lin)
                    elif isinstance(layer.ffn, ParallelGatedMLP):
                        layer.ffn.l1 = assign_lora(layer.ffn.l1)
                        layer.ffn.l2 = assign_lora(layer.ffn.l2)
                        layer.ffn.l3 = assign_lora(layer.ffn.l3)
                    else:
                        raise NotImplementedError
                if self.lora_norm:
                    assert isinstance(layer.norm_attn.normalizer, RMSNorm)
                    assert isinstance(layer.norm_ffn.normalizer, RMSNorm)
                    layer.norm_attn.normalizer = assign_lora(layer.norm_attn.normalizer)
                    layer.norm_ffn.normalizer = assign_lora(layer.norm_ffn.normalizer)
        assign_transformer(encoder.global_layers)
        assign_transformer(encoder.sparse_layers)
        for (i, layer) in enumerate(encoder.global_linears):
            if self.lora_fusion:
                encoder.global_linears[i] = assign_lora(layer)
        for (i, layer) in enumerate(encoder.sparse_linears):
            if self.lora_fusion:
                encoder.sparse_linears[i] = assign_lora(layer)
        if self.lora_norm and encoder.post_layers_norm is not None:
            encoder.post_layers_norm.normalizer = assign_lora(encoder.post_layers_norm.normalizer)
        return encoder

    def forward(self, td: Tensor, mask: Union[Tensor, None]=None) -> Tuple[Tensor, Tensor]:
        return self.encoder(td, mask)

# Component: CadaMultiLoRAEncoder
class CadaMultiLoRAEncoder(CadaLoRAEncoder):

    def __init__(self, encoder: CadaEncoder=None, lora_rank: int=64, lora_alpha: float=0.5, lora_act_func: str='softmax', lora_n_experts: int=4, lora_top_k: int=4, lora_temperature: float=1.0, lora_use_trainable_layer: bool=False, lora_use_dynamic_topK: bool=False, lora_use_basis_variants: bool=False, lora_use_linear: bool=False, lora_use_basis_variants_as_input: bool=False, lora_init_embed: bool=True, lora_prompt_embed: bool=True, lora_query: bool=True, lora_key: bool=True, lora_value: bool=True, lora_projection: bool=True, lora_ffn: bool=True, lora_fusion: bool=True, lora_norm: bool=True, assign_lora: Callable=None):
        if assign_lora == None:
            assign_lora = partial(LinearWithGatedMultiLoRA, rank=lora_rank, alpha=lora_alpha, act_func=lora_act_func, n_experts=lora_n_experts, top_k=lora_top_k, temperature=lora_temperature, use_trainable_layer=lora_use_trainable_layer, use_dynamic_topK=lora_use_dynamic_topK, use_basis_variants=lora_use_basis_variants, use_basis_variants_as_input=lora_use_basis_variants_as_input, use_linear=lora_use_linear)
        super(CadaMultiLoRAEncoder, self).__init__(encoder=encoder, lora_init_embed=lora_init_embed, lora_prompt_embed=lora_prompt_embed, lora_query=lora_query, lora_key=lora_key, lora_value=lora_value, lora_projection=lora_projection, lora_ffn=lora_ffn, lora_fusion=lora_fusion, lora_norm=lora_norm, assign_lora=assign_lora)

# Component: LoRALayer
class LoRALayer(nn.Module):

    def __init__(self, input_dim, output_dim, rank, alpha=1.0, use_linear=False):
        super(LoRALayer, self).__init__()
        self.rank = rank
        self.alpha = alpha
        self.use_linear = use_linear
        std_dev = 1 / torch.sqrt(torch.tensor(rank).float())
        if not use_linear:
            self.A = torch.nn.Parameter(torch.randn(input_dim, rank) * std_dev)
            self.B = torch.nn.Parameter(torch.zeros(rank, output_dim))
        else:
            self.weight = torch.nn.Parameter(torch.zeros(input_dim, output_dim))

    def forward(self, x, *args, **kwargs):
        if not self.use_linear:
            output = self.alpha * (x @ self.A @ self.B)
        else:
            output = self.alpha * (x @ self.weight)
        return output

# Component: LoRANorm
class LoRANorm(nn.Module):

    def __init__(self, dim: int, alpha: float=1.0, eps: float=1e-05, **kwargs):
        super().__init__()
        self.eps = eps
        self.alpha = alpha
        self.weight = nn.Parameter(torch.ones(dim))

    def _norm(self, x):
        return x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)

    def forward(self, x):
        output = self._norm(x.float()).type_as(x)
        return self.alpha * output * self.weight

# Component: GateLayer
class GateLayer(nn.Module):

    def __init__(self, input_dim, ouptut_dim=1, act_func=None):
        super(GateLayer, self).__init__()
        self.gate_weight = torch.nn.Parameter(torch.zeros(input_dim, ouptut_dim))
        if act_func == 'sigmoid':
            self.act_func = torch.nn.Sigmoid()
        elif act_func == None:
            self.act_func = torch.nn.Identity()
        else:
            raise NotImplementedError

    def forward(self, x):
        output = self.act_func(x @ self.gate_weight)
        return output

# Component: LinearWithLoRA
class LinearWithLoRA(nn.Module):

    def __init__(self, linear_layer, rank=64, alpha=1.0, use_gate=True, act_func='sigmoid', use_linear=False):
        super(LinearWithLoRA, self).__init__()
        self.linear_layer = linear_layer
        self.use_gate = use_gate
        if isinstance(linear_layer, nn.Linear):
            input_dim = linear_layer.in_features
            output_dim = linear_layer.out_features
            self.lora_layer = LoRALayer(input_dim, output_dim, rank, alpha, use_linear=use_linear)
        elif isinstance(linear_layer, RMSNorm):
            assert linear_layer.weight.dim() == 1
            input_dim = linear_layer.weight.size(0)
            output_dim = input_dim
            self.lora_layer = LoRANorm(input_dim, alpha)
        if use_gate:
            self.gate_layer = GateLayer(input_dim, act_func=act_func)
        else:
            self.gate_layer = None

    def forward(self, x, *args, **kwargs):
        if self.use_gate:
            output = self.gate_layer(x) * self.linear_layer(x, *args, **kwargs) + self.lora_layer(x)
        else:
            output = self.linear_layer(x, *args, **kwargs) + self.lora_layer(x)
        return output

# Component: GatedMultiLoRALayer
class GatedMultiLoRALayer(nn.Module):

    def __init__(self, input_dim, output_dim, rank, alpha, act_func, n_experts, top_k, temperature, linear_layer, use_trainable_layer: bool=False, use_dynamic_topK: bool=False, use_basis_variants: bool=False, use_linear: bool=False, use_basis_variants_as_input: bool=False):
        super(GatedMultiLoRALayer, self).__init__()
        self.input_dim = input_dim
        self.output_dim = output_dim
        self.act_func = act_func
        self.n_experts = n_experts
        self.top_k = top_k
        self.temperature = temperature
        self.linear_layer = linear_layer
        assert self.top_k <= self.n_experts
        self.use_trainable_layer = use_trainable_layer
        self.use_dynamic_topK = use_dynamic_topK
        self.use_basis_variants = use_basis_variants
        self.use_basis_variants_as_input = use_basis_variants_as_input
        self.basis_variant_binary_vector = None
        if isinstance(linear_layer, nn.Linear):
            self.lora_layers = nn.ModuleList([LoRALayer(input_dim, output_dim, rank[_], alpha, use_linear=use_linear) for _ in range(n_experts if not use_trainable_layer else n_experts + 1)])
        elif isinstance(linear_layer, RMSNorm):
            self.lora_layers = nn.ModuleList([LoRANorm(input_dim, alpha=alpha) for _ in range(n_experts if not use_trainable_layer else n_experts + 1)])
        if not use_basis_variants_as_input:
            self.gate_layers = nn.ModuleList([GateLayer(input_dim) for _ in range(n_experts + 1)])
        else:
            self.gate_layers = nn.ModuleList([GateLayer(input_dim + n_experts) for _ in range(n_experts + 1)])

    def normalize_logits(self, logits, dim):
        if self.act_func == 'softmax':
            output = F.softmax(logits / self.temperature, dim=dim)
        elif self.act_func == 'softplus':
            output = F.softplus(logits / self.temperature)
            output = output / output.sum(dim=dim, keepdim=True)
        elif self.act_func == 'sigmoid':
            output = F.sigmoid(logits)
        else:
            raise NotImplementedError
        return output

    def wrap_basis_variant_binary_vector(self, x, basis_variant_binary_vector):
        assert basis_variant_binary_vector.size() == (x.size(0), self.n_experts)
        if len(basis_variant_binary_vector.size()) != len(x.size()):
            assert len(basis_variant_binary_vector.size()) < len(x.size())
            basis_variant_binary_vector = basis_variant_binary_vector[:, None, :].expand(x.size(0), x.size(1), self.n_experts)
            basis_variant_binary_vector = basis_variant_binary_vector.reshape(-1, self.n_experts)
        return basis_variant_binary_vector

    def reset_basis_variant_binary_vector(self):
        self.basis_variant_binary_vector = None

    def forward(self, x, *args, **kwargs):
        base_output = self.linear_layer(x, *args, **kwargs)
        basis_variant_binary_vector = self.basis_variant_binary_vector
        basis_variant_binary_vector = self.wrap_basis_variant_binary_vector(x, basis_variant_binary_vector)
        output_shape = list(x.size()[:-1]) + [self.output_dim]
        n_nodes = np.prod(x.size()[:-1])
        x = x.reshape(-1, self.input_dim) if x.dim() != 2 else x
        base_output = base_output.reshape(-1, self.output_dim) if base_output.dim != 2 else base_output
        outputs = torch.stack([lora_layer(x) for lora_layer in self.lora_layers[:self.n_experts]]).permute(1, 0, 2)
        outputs = torch.cat((base_output[:, None, :], outputs), dim=1)
        if self.use_dynamic_topK:
            gates = self.dynamic_top_k_gating(x, basis_variant_binary_vector)
        else:
            gates = self.static_top_k_gating(x, top_k=self.top_k, basis_variant_binary_vector=basis_variant_binary_vector)
        if self.use_trainable_layer:
            outputs = (outputs * gates[..., None]).sum(1) + self.lora_layers[self.n_experts](x)
        else:
            outputs = (outputs * gates[..., None]).sum(1)
        return outputs.reshape(output_shape)

    def dynamic_top_k_gating(self, x, basis_variant_binary_vector):
        if self.use_basis_variants_as_input:
            x = torch.cat((x, basis_variant_binary_vector), dim=-1)
        logits = torch.cat([gate_layer(x) for gate_layer in self.gate_layers], dim=1)
        top_k = basis_variant_binary_vector.sum(-1, keepdim=True).to(torch.int64)
        assert basis_variant_binary_vector.size() == (x.size(0), self.n_experts)
        assert (logits.size(-1) - 1 >= top_k).all() and logits.size(-1) == self.n_experts + 1
        (base_logits, lora_logits) = (logits[:, :1], logits[:, 1:self.n_experts + 1])
        if self.use_basis_variants:
            lora_logits[~basis_variant_binary_vector.bool()] = float('-inf')
        else:
            sorted_lora_logits = lora_logits.sort(dim=-1, descending=True)[0]
            threshold_index = torch.clamp(top_k - 1, 0, self.n_experts - 1)
            threshold = sorted_lora_logits.gather(index=threshold_index, dim=-1)
            lora_logits[lora_logits < threshold] = float('-inf')
            lora_logits[(top_k == 0).expand_as(lora_logits)] = float('-inf')
        logits = torch.cat((base_logits, lora_logits), dim=-1)
        gates = self.normalize_logits(logits, dim=-1)
        return gates

    def static_top_k_gating(self, x, top_k, basis_variant_binary_vector):
        if self.use_basis_variants_as_input:
            x = torch.cat((x, basis_variant_binary_vector), dim=-1)
        logits = torch.cat([gate_layer(x) for gate_layer in self.gate_layers], dim=1)
        assert logits.size(-1) - 1 >= top_k and logits.size(-1) == self.n_experts + 1
        (base_logits, lora_logits) = (logits[:, :1], logits[:, 1:self.n_experts + 1])
        (top_logits, top_indices) = lora_logits.topk(top_k, dim=-1)
        zeros = torch.zeros_like(lora_logits, requires_grad=True)
        lora_logits = zeros.scatter(dim=-1, index=top_indices, src=top_logits)
        logits = torch.cat((base_logits, lora_logits), dim=-1)
        gates = self.normalize_logits(logits, dim=-1)
        return gates

# Component: LinearWithGatedMultiLoRA
class LinearWithGatedMultiLoRA(nn.Module):

    def __init__(self, linear_layer, rank=64, alpha=1.0, act_func='softmax', n_experts=4, top_k=4, temperature=1.0, use_trainable_layer=False, use_dynamic_topK=False, use_basis_variants=False, use_linear=False, use_basis_variants_as_input=False):
        super(LinearWithGatedMultiLoRA, self).__init__()
        self.linear_layer = linear_layer
        if isinstance(linear_layer, nn.Linear):
            input_dim = linear_layer.in_features
            output_dim = linear_layer.out_features
        elif isinstance(linear_layer, RMSNorm):
            assert linear_layer.weight.dim() == 1
            input_dim = linear_layer.weight.size(0)
            output_dim = input_dim
        self.lora_layer = GatedMultiLoRALayer(input_dim=input_dim, output_dim=output_dim, rank=rank, alpha=alpha, act_func=act_func, n_experts=n_experts, top_k=top_k, temperature=temperature, use_trainable_layer=use_trainable_layer, use_dynamic_topK=use_dynamic_topK, use_basis_variants=use_basis_variants, use_linear=use_linear, use_basis_variants_as_input=use_basis_variants_as_input, linear_layer=linear_layer)

    def forward(self, x, *args, **kwargs):
        output = self.lora_layer(x, *args, **kwargs)
        return output

# Component: _to_tensor
def _to_tensor(x) -> torch.Tensor:
    t = torch.as_tensor(x)
    if t.ndim > 0 and t.shape[0] == 1:
        t = t.squeeze(0)
    return t.detach().cpu()

# Component: _float_scalar
def _float_scalar(x, default: float=0.0) -> float:
    if x is None:
        return default
    t = torch.as_tensor(x).detach().cpu().reshape(-1)
    return float(t[0].item()) if t.numel() else default

# Component: _canonical_vrp_item
def _canonical_vrp_item(dataset_name: str, item) -> Dict:
    ident = parse_dataset_identity(dataset_name)
    variant = ident['variant']
    if ident['problem'] == 'CVRP':
        depot_xy = _to_tensor(item['depot'])
        node_xy = _to_tensor(item['loc'])
        node_demand = _to_tensor(item['demand']).float()
        if node_xy.ndim == 2 and node_xy.shape[0] == node_demand.shape[0] and (node_xy.shape[0] >= 1) and torch.allclose(node_xy[:1].float(), depot_xy.float()) and (float(node_demand[0].item()) == 0.0):
            node_xy = node_xy[1:]
            node_demand = node_demand[1:]
        capacity = 1.0
        route_limit = None
        service_time = None
        tw_start = None
        tw_end = None
    else:
        depot_xy = _to_tensor(item['depot_xy'])
        node_xy = _to_tensor(item['node_xy'])
        node_demand = _to_tensor(item['node_demand']).float()
        capacity = _float_scalar(item.get('capacity'), default=1.0)
        route_limit = item.get('route_limit')
        service_time = item.get('service_time')
        tw_start = item.get('tw_start')
        tw_end = item.get('tw_end')
    if depot_xy.ndim == 1:
        depot_xy = depot_xy.unsqueeze(0)
    linehaul = node_demand.clamp(min=0)
    backhaul = (-node_demand).clamp(min=0)
    locs = torch.cat([depot_xy.float(), node_xy.float()], dim=0)
    depot_zeros = torch.zeros(1, dtype=torch.float32)
    demand_linehaul = linehaul.float()
    demand_backhaul = backhaul.float()
    if service_time is None:
        service_time_full = torch.zeros(locs.shape[0], dtype=torch.float32)
    else:
        service_time_full = torch.cat([depot_zeros, _to_tensor(service_time).float()], dim=0)
    if tw_start is None or tw_end is None:
        time_windows = torch.zeros(locs.shape[0], 2, dtype=torch.float32)
        time_windows[:, 1] = float('inf')
    else:
        tw_start_t = _to_tensor(tw_start).float()
        tw_end_t = _to_tensor(tw_end).float()
        depot_tw = torch.tensor([[0.0, float('inf')]], dtype=torch.float32)
        customer_tw = torch.stack([tw_start_t, tw_end_t], dim=-1)
        time_windows = torch.cat([depot_tw, customer_tw], dim=0)
    open_route = torch.tensor([variant.startswith('ovrp')], dtype=torch.bool)
    distance_limit = torch.tensor([_float_scalar(route_limit, default=float('inf'))], dtype=torch.float32)
    vehicle_capacity = torch.tensor([1.0], dtype=torch.float32)
    capacity_original = torch.tensor([capacity], dtype=torch.float32)
    speed = torch.tensor([1.0], dtype=torch.float32)
    return {'scale': int(node_xy.shape[0]), 'variant': variant, 'locs': locs, 'demand_linehaul': demand_linehaul, 'demand_backhaul': demand_backhaul, 'distance_limit': distance_limit, 'time_windows': time_windows, 'service_time': service_time_full, 'vehicle_capacity': vehicle_capacity, 'capacity_original': capacity_original, 'open_route': open_route, 'speed': speed}

