            LoRAPolicy.load_basis_policy_weights(basis_policy, basis_policy_ckpt_path)
        LoRAPolicy.fix_basis_policy_weights(basis_policy)
        encoder = MultiLoRAEncoder(encoder=basis_policy.encoder, lora_rank=lora_rank, lora_alpha=lora_alpha, lora_act_func=lora_act_func, lora_n_experts=lora_n_experts, lora_top_k=lora_top_k, lora_temperature=lora_temperature, lora_use_trainable_layer=lora_use_trainable_layer, lora_use_dynamic_topK=lora_use_dynamic_topK, lora_use_basis_variants=lora_use_basis_variants, lora_use_linear=lora_use_linear, lora_use_basis_variants_as_input=lora_use_basis_variants_as_input)
        decoder = MultiLoRADecoder(decoder=basis_policy.decoder, lora_rank=lora_rank, lora_alpha=lora_alpha, lora_act_func=lora_act_func, lora_n_experts=lora_n_experts, lora_top_k=lora_top_k, lora_temperature=lora_temperature, lora_use_trainable_layer=lora_use_trainable_layer, lora_use_dynamic_topK=lora_use_dynamic_topK, lora_use_basis_variants=lora_use_basis_variants, lora_use_linear=lora_use_linear, lora_use_basis_variants_as_input=lora_use_basis_variants_as_input)
        super(MultiLoRAPolicy, self).__init__(encoder=encoder, decoder=decoder, embed_dim=embed_dim, num_heads=num_heads, normalization=normalization, feedforward_hidden=feedforward_hidden, env_name=env_name, use_graph_context=use_graph_context, context_embedding=context_embedding, **kwargs)
        self.lora_n_experts = lora_n_experts
        lora_fixed_params = self.lora_fixed_params()
        if lora_modules_ckpt_path != None:
            self.load_lora_modules(lora_fixed_params, lora_modules_ckpt_path)

    def lora_fixed_params(self) -> Dict[str, Any]:
        state_dict = {}
        for (name, module) in self.named_parameters():
            if 'lora_layers' in name.split('.'):
                lora_num_idx = name.split('.').index('lora_layers') + 1
                if int(name.split('.')[lora_num_idx]) < self.lora_n_experts:
                    state_dict[name] = module
                    module.requires_grad = False
        return state_dict

    def load_lora_modules(self, lora_fixed_params, lora_modules_ckpt_path):
        multi_lora_state_dict = collect_multi_lora_state_dict(multi_lora_fixed_params=lora_fixed_params, lora_n_experts=self.lora_n_experts)
        assert len(lora_modules_ckpt_path) == len(multi_lora_state_dict)
        for (source_lora_ckpt_path, target_state_dict) in zip(lora_modules_ckpt_path, multi_lora_state_dict.values()):
            assert os.path.exists(source_lora_ckpt_path)
            source_state_dict = collect_lora_state_dict(ckpt_path=source_lora_ckpt_path)
            load_target_lora_module(source_state_dict, target_state_dict)

    def lora_trainable_params(self, return_dict=False) -> Union[List, Any]:
        trainable_params = {}
        for (name, module) in self.named_parameters():
            if 'lora_layers' in name.split('.'):
                lora_num_idx = name.split('.').index('lora_layers') + 1
                if int(name.split('.')[lora_num_idx]) == self.lora_n_experts:
                    assert name.split('.')[lora_num_idx - 2] == 'lora_layer'
                    assert module.requires_grad == True
                    trainable_params[name] = module
            elif 'gate_layers' in name.split('.'):
                assert name.split('.')[name.split('.').index('gate_layers') - 1] == 'lora_layer'
                assert module.requires_grad == True
                trainable_params[name] = module
        assert len(trainable_params) > 0
        if return_dict:
            return trainable_params
        else:
            return list(trainable_params.values())

    def collect_GatedMultiLoRALayer(self):
        self.GatedMultiLoRALayer = []
        for module in self.encoder.modules():
            if isinstance(module, GatedMultiLoRALayer):
                self.GatedMultiLoRALayer.append(module)
        for module in self.decoder.modules():
            if isinstance(module, GatedMultiLoRALayer):
                self.GatedMultiLoRALayer.append(module)

    def get_basis_variant_binary_vector(self, td):
        (has_open, has_tw, has_limit, has_backhaul, backhaul_class) = MTVRPEnv.check_variants(td)
        prompt = torch.stack((has_open, has_tw, has_limit, has_backhaul), dim=-1).to(torch.float32)
        return prompt

    def set_basis_variant_binary_vector(self, td):
        basis_variant_binary_vector = self.get_basis_variant_binary_vector(td)
        for module in self.GatedMultiLoRALayer:
            module.basis_variant_binary_vector = basis_variant_binary_vector
        return

    def forward(self, td: TensorDict, env=None, phase: str='train', calc_reward: bool=True, return_actions: bool=True, return_entropy: bool=False, return_hidden: bool=False, return_init_embeds: bool=False, return_sum_log_likelihood: bool=True, actions=None, max_steps=1000000, **decoding_kwargs) -> dict:
        self.collect_GatedMultiLoRALayer()
        self.set_basis_variant_binary_vector(td)
        outdict = super(MultiLoRAPolicy, self).forward(td=td, env=env, phase=phase, calc_reward=calc_reward, return_actions=return_actions, return_entropy=return_entropy, return_hidden=return_hidden, return_init_embeds=return_init_embeds, return_sum_log_likelihood=return_sum_log_likelihood, actions=actions, max_steps=max_steps, **decoding_kwargs)
        return outdict

# Component: LoRADecoder
class LoRADecoder(nn.Module):

    def __init__(self, decoder: AttentionModelDecoder=None, lora_rank: int=64, lora_alpha: float=0.5, lora_use_gate: bool=True, lora_act_func: str='sigmoid', lora_use_linear: bool=False, lora_context_embed: bool=True, lora_glimpse_key: bool=True, lora_glimpse_value: bool=True, lora_logit_key: bool=True, lora_fixed_context: bool=True, lora_pointer: bool=True, assign_lora: Callable=None):
        super(LoRADecoder, self).__init__()
        if assign_lora == None:
            assign_lora = partial(LinearWithLoRA, rank=lora_rank, alpha=lora_alpha, use_gate=lora_use_gate, act_func=lora_act_func, use_linear=lora_use_linear)
        self.lora_context_embed = lora_context_embed
        self.lora_glimpse_value = lora_glimpse_value
        self.lora_glimpse_key = lora_glimpse_key
        self.lora_logit_key = lora_logit_key
        self.lora_fixed_context = lora_fixed_context
        self.lora_pointer = lora_pointer
        self.decoder = self.assign_lora_layers(decoder, assign_lora)

    def assign_lora_layers(self, decoder, assign_lora):
        assert decoder.is_dynamic_embedding == False
        assert isinstance(decoder.context_embedding, MTVRPContextEmbeddingRouteFinder)
        if self.lora_context_embed:
            decoder.context_embedding.project_context = assign_lora(decoder.context_embedding.project_context)
        if self.lora_glimpse_key:
            decoder.project_glimpse_key = assign_lora(decoder.project_glimpse_key)
        if self.lora_glimpse_value:
            decoder.project_glimpse_value = assign_lora(decoder.project_glimpse_value)
        if self.lora_logit_key:
            decoder.project_logit_key = assign_lora(decoder.project_logit_key)
        if decoder.use_graph_context and self.lora_fixed_context:
            decoder.project_fixed_context = assign_lora(decoder.project_fixed_context)
        if self.lora_pointer:
            decoder.pointer.project_out = assign_lora(decoder.pointer.project_out)
        return decoder

    def forward(self, td: TensorDict, cached: PrecomputedCache, num_starts: int=0) -> Tuple[Tensor, Tensor]:
        return self.decoder(td, cached, num_starts)

    def _precompute_cache(self, embeddings: torch.Tensor, num_starts: int=0) -> PrecomputedCache:
        return self.decoder._precompute_cache(embeddings, num_starts)

    def pre_decoder_hook(self, td, env, embeddings, num_starts: int=0) -> Tuple[TensorDict, RL4COEnvBase, PrecomputedCache]:
        return self.decoder.pre_decoder_hook(td, env, embeddings, num_starts)

# Component: MultiLoRADecoder
class MultiLoRADecoder(LoRADecoder):

    def __init__(self, decoder: AttentionModelDecoder=None, lora_rank: int=64, lora_alpha: float=0.5, lora_act_func: str='softmax', lora_n_experts: int=4, lora_top_k: int=4, lora_temperature: float=1.0, lora_use_trainable_layer: bool=False, lora_use_dynamic_topK: bool=False, lora_use_basis_variants: bool=False, lora_use_linear: bool=False, lora_use_basis_variants_as_input: bool=False, lora_context_embed: bool=True, lora_glimpse_key: bool=True, lora_glimpse_value: bool=True, lora_logit_key: bool=True, lora_fixed_context: bool=True, lora_pointer: bool=True, assign_lora: Callable=None):
        if assign_lora == None:
            assign_lora = partial(LinearWithGatedMultiLoRA, rank=lora_rank, alpha=lora_alpha, act_func=lora_act_func, n_experts=lora_n_experts, top_k=lora_top_k, temperature=lora_temperature, use_trainable_layer=lora_use_trainable_layer, use_dynamic_topK=lora_use_dynamic_topK, use_basis_variants=lora_use_basis_variants, use_linear=lora_use_linear, use_basis_variants_as_input=lora_use_basis_variants_as_input)
        super(MultiLoRADecoder, self).__init__(decoder=decoder, lora_context_embed=lora_context_embed, lora_glimpse_key=lora_glimpse_key, lora_glimpse_value=lora_glimpse_value, lora_logit_key=lora_logit_key, lora_fixed_context=lora_fixed_context, lora_pointer=lora_pointer, assign_lora=assign_lora)

