# Component: AttentionModelEncoder
class AttentionModelEncoder(nn.Module):

    def __init__(self, env_name: str='tsp', embed_dim: int=128, init_embedding: nn.Module=None, num_heads: int=8, qkv_dim: int=16, num_layers: int=3, normalization: str='batch', feedforward_hidden: int=512, net: nn.Module=None, bias: bool=False, bias_k: bool=None, bias_v: bool=None, bias_combine: bool=True):
        super(AttentionModelEncoder, self).__init__()
        self.env_name = env_name
        self.initial_embedding = initial_embedding(self.env_name, {'embed_dim': embed_dim}) if init_embedding is None else init_embedding
        self.net = TransformerNet(num_layers, num_heads, qkv_dim, embed_dim, normalization, feedforward_hidden, bias=bias, bias_k=bias_k, bias_v=bias_v, bias_combine=bias_combine) if net is None else net

    def forward(self, td: TensorDict, mask: Optional[Tensor]=None, weights=None) -> Tuple[Tensor, Tensor]:
        if weights is None:
            init_out = self.initial_embedding(td)
            out = self.net(init_out)
        else:
            init_out = self.initial_embedding(td, weights=weights)
            out = self.net(init_out, weights=weights)
        return (out, init_out)

Solver implementation role: inference

# Component: OMNIInitialization.run
def run(self, env: EnvBase, batch: int, strategy: str, phase: Literal['train', 'eval'], **kwargs) -> Tuple[TensorDict, Any]:
    if phase == 'train':
        meta_params = kwargs.get('meta_params', {})
        current_epoch = kwargs.get('current_epoch')
        meta_optimizer = self.optimizers()
        meta_optimizer.zero_grad()
        if self.so_to_fo:
            if current_epoch > meta_params['switch_epochs']:
                meta_params['meta_method'] = 'fomaml'
            else:
                meta_params['meta_method'] = 'maml'
        if meta_params['data_type'] == 'size_distribution':
            start = self.min_n + int(min(current_epoch / meta_params['sch_epoch'], 1) * (self.max_n - self.min_n))
            n = start // self.task_interval * self.task_interval
            idx = (n - self.min_n) // self.task_interval
            (tasks, weights) = (self.task_set[idx * 11:(idx + 1) * 11], self.task_w[idx])
            if current_epoch + 1 % meta_params['update_weight'] == 0:
                self.task_w[idx] = _update_task_weight(self, tasks, weights, meta_params, env)
        (val_loss, meta_grad_dict) = (0, {(i, j): 0 for (i, group) in enumerate(meta_optimizer.param_groups) for (j, _) in enumerate(group['params'])})
        meta_batch_size = meta_params['meta_batch_size']
        (w, selected_tasks) = ([1.0] * meta_params['B'], [])
        for b in range(meta_params['B']):
            if meta_params['data_type'] == 'size_distribution':
                selected = torch.multinomial(self.task_w[idx], 1).item()
                task_params = tasks[selected]
                w[b] = self.task_w[idx][selected].item()
                batch_size = meta_batch_size if task_params[0] <= 150 else meta_batch_size // 2
            selected_tasks.append(task_params)
        w = torch.softmax(torch.Tensor(w), dim=0)
        for b in range(meta_params['B']):
            (task_params, task_w) = (selected_tasks[b], w[b].item())
            if meta_params['meta_method'] == 'fomaml':
                task_model = copy.deepcopy(self.policy)
                optimizer = Optimizer(task_model.parameters(), **self.optimizer_params['optimizer'])
            elif meta_params['meta_method'] == 'maml':
                fast_weight = OrderedDict(self.policy.named_parameters())
            for step in range(meta_params['k']):
                (data, norm_data) = get_data(meta_params['data_type'], batch_size, task_params, env.problem_size, env.env_name)
                if env.env_name == 'tsp':
                    env.pomo_size = norm_data.size(1)
                    env.problem_size = norm_data.size(1)
                else:
                    env.pomo_size = norm_data.size(1) - 1
                    env.problem_size = norm_data.size(1) - 1
                env.load_problems(norm_data, batch_size)
                self.policy.train()
                if meta_params['meta_method'] == 'fomaml':
                    task_model.train()
                    (state_td, policy_out) = self.play_episode(env, 'sampling', policy=task_model)
                    loss = self.calculate_loss(policy_out)
                    optimizer.zero_grad()
                    loss.backward()
                    optimizer.step()
                elif meta_params['meta_method'] == 'maml':
                    (state_td, policy_out) = self.play_episode(env, 'sampling', weights=fast_weight)
                    loss = self.calculate_loss(policy_out)
                    fast_weight = manual_adam_omni(self=self, loss=loss, fast_weight=fast_weight, meta_optimizer=meta_optimizer)
                reward = policy_out['reward']
            (val_data, norm_val_data) = get_data(meta_params['data_type'], batch_size, task_params, env.problem_size, env.env_name)
            if meta_params['meta_method'] == 'maml':
                val_loss = _fast_val(self, env, fast_weight, data=norm_val_data, mode='maml')
                loss = meta_params['beta'] * val_loss * task_w
                meta_optimizer.zero_grad()
                loss.backward()
                for (i, group) in enumerate(meta_optimizer.param_groups):
                    for (j, p) in enumerate(group['params']):
                        if p.grad is None:
                            continue
                        else:
                            meta_grad_dict[i, j] += p.grad
            elif meta_params['meta_method'] == 'fomaml':
                val_loss = _fast_val(self, env, task_model, data=val_data, mode='fomaml')
                loss = meta_params['beta'] * val_loss * task_w
                optimizer.zero_grad()
                loss.backward()
                for (i, group) in enumerate(optimizer.param_groups):
                    for (j, p) in enumerate(group['params']):
                        if p.grad is None:
                            continue
                        else:
                            meta_grad_dict[i, j] += p.grad
        meta_optimizer.zero_grad()
        for (i, group) in enumerate(meta_optimizer.param_groups):
            for (j, p) in enumerate(group['params']):
                if isinstance(meta_grad_dict[i, j], int):
                    continue
                else:
                    p.grad = meta_grad_dict[i, j]
        meta_optimizer.step()
        ret = {}
        ret['batch_size'] = batch_size
        ret['reward'] = reward
        ret['loss'] = loss
        return (ret, ret)
    else:
        self.policy.eval()
        with torch.inference_mode():
            env.load_problems(batch, batch_size=batch.size(0))
            (state_td, policy_out) = self.play_episode(env, strategy)
        aug_reward = policy_out['reward'].reshape(env.aug_factor, batch.size(0), env.pomo_size)
        (max_pomo_reward, _) = aug_reward.max(dim=2)
        no_aug_reward = -max_pomo_reward[0, :].float().mean()
        (max_aug_pomo_reward, _) = max_pomo_reward.max(dim=0)
        aug_score = -max_aug_pomo_reward.float().mean()
        out = {'no_aug_score': no_aug_reward, 'aug_score': aug_score}
        fast_val_flag = kwargs.get('fast_val_flag')
        if fast_val_flag is not None:
            return (no_aug_reward, aug_score, max_pomo_reward)
        return (state_td, out)

# Component: OMNIInitialization.play_episode
def play_episode(self, env, decoder_strategy: str='sampling', weights=None, policy=None) -> Tuple[TensorDict, dict]:
    if policy is None:
        policy = self.policy
    reset_td = env.reset()
    policy.set_decoder_strategy(decoder_strategy)
    if weights is None:
        policy.pre_forward(reset_td)
    else:
        policy.pre_forward(reset_td, weights=weights)
    log_likelihood = torch.zeros(size=(env.batch_size[0], env.pomo_size, 0))
    done = False
    reward = None
    state_td = env.pre_step()
    while not done:
        if weights is None:
            next_td = policy(state_td)
        else:
            next_td = policy(state_td, weights=weights)
        prob = next_td['prob']
        state_td = env.step(next_td)
        log_likelihood = torch.cat((log_likelihood, prob[:, :, None]), dim=2)
        reward = state_td['reward']
        done = state_td['done'].all()
    policy_out = {'reward': reward, 'likelihood': log_likelihood}
    return (state_td, policy_out)

# Component: TSPEnv.load_problems
def load_problems(self, dataset, batch_size: int=64):
    self.problems = dataset
    if self.method_name == 'udc':
        self.problem_size = self.problems.size(1)
    self.raw_problems = dataset
    self.env_batch_size = batch_size
    self.batch_size = torch.Size([batch_size, self.pomo_size])
    if self.aug_flag is True:
        self.pomo_size = min(self.pomo_size, 5000)
        self.batch_size = torch.Size([self.env_batch_size * self.aug_factor, self.pomo_size])
        self.env_batch_size = self.env_batch_size * self.aug_factor
        aug_operator = {'pomo_aug': augment_pomo, 'rotate': augment_rotate, 'reflect': augment_reflect, 'mix': augment_mix, 'noise': augment_noise}
        if self.aug_type not in aug_operator:
            raise NotImplementedError(f'Augment type {self.aug_type} is not supported.')
        self.problems = aug_operator[self.aug_type](problems=self.problems, aug_factor=self.aug_factor, mix_prop=self.mix_prop)
        if self.aug_type != 'pomo_aug':
            self.problems[:self.batch_size[0] // self.aug_factor] = self.raw_problems
    assert self.env_batch_size == self.problems.size(0), 'batch_size and the first dimension of problems should be the same. ' + f'Expected batch_size: {self.problems.size(0)}, got: {self.env_batch_size}'
    self.dist = (self.problems[:, :, None, :] - self.problems[:, None, :, :]).norm(p=2, dim=-1).to(self.device)

# Component: TSPEnv._reset
def _reset(self, td: TensorDict, batch_size=None) -> TensorDict:
    self.output_spec = None
    self.current_node = None
    self.selected_node_list = torch.zeros((self.env_batch_size, self.pomo_size, 0), dtype=torch.long)
    self.ninf_mask = torch.zeros((self.env_batch_size, self.pomo_size, self.problems.shape[1]))
    self.dummy_flag_bool = torch.zeros((self.env_batch_size, self.pomo_size), dtype=torch.bool)
    self.dummy_flag_long = torch.zeros((self.env_batch_size, self.pomo_size), dtype=torch.long) - 1
    self.selected_count = torch.zeros((self.env_batch_size, self.pomo_size), dtype=torch.long)
    if self.method_name == 'udc':
        self.ninf_mask[:, :self.pomo_size // 2, -1] = float('-inf')
        self.ninf_mask[:, self.pomo_size // 2:, 0] = float('-inf')
        self.selected_count += 1
        self.first_node = self.dummy_flag_long
    return TensorDict({'action': self.dummy_flag_long, 'locs': self.problems, 'ninf_mask': self.ninf_mask, 'selected_count': self.selected_count, 'selected_node_list': self.selected_node_list, 'reward': self.dummy_flag_long, 'done': self.dummy_flag_bool}, batch_size=torch.Size([self.env_batch_size]))

# Component: TSPEnv.pre_step
def pre_step(self) -> TensorDict:
    next_state = {'ninf_mask': self.ninf_mask, 'selected_count': self.selected_count, 'selected_node_list': self.selected_node_list}
    if self.method_name == 'elg' and self.current_node is not None:
        local_feature = self._get_local_feature()
        out = TensorDict({'action': self.dummy_flag_long, 'first_node': self.dummy_flag_long, 'next': next_state, 'local_feature': local_feature, 'reward': self.dummy_flag_long, 'done': self.dummy_flag_bool}, batch_size=self.batch_size)
    else:
        out = TensorDict({'action': self.dummy_flag_long, 'first_node': self.dummy_flag_long, 'next': next_state, 'reward': self.dummy_flag_long, 'done': self.dummy_flag_bool}, batch_size=self.batch_size)
    return out

# Component: TSPEnv._step
def _step(self, td: TensorDict) -> TensorDict:
    self.selected_count += 1
    self.current_node = td['action']
    self.selected_node_list = torch.cat((self.selected_node_list, self.current_node[:, :, None]), dim=2)
    if self.selected_count[0, 0] == 1:
        self.first_node = self.current_node
    self.ninf_mask.scatter_(dim=-1, index=self.current_node.unsqueeze(-1), value=float('-inf'))
    done = self.selected_count == self.problems.shape[1]
    done_all = done.all()
    if done_all:
        assert (self.ninf_mask == float('-inf')).all(), 'The selected nodes should be masked with -inf. It means that the certain solutions are not valid.'
        if self.method_name == 'udc':
            self.selected_node_list = torch.cat((self.selected_node_list, torch.cat((self.problem_size - torch.ones(self.pomo_size // 2)[None, :].expand(self.env_batch_size, self.pomo_size // 2), torch.zeros(self.pomo_size // 2)[None, :].expand(self.env_batch_size, self.pomo_size // 2)), dim=-1).long()[:, :, None]), dim=2)
            reward = -self._get_travel_distance(selected_node_list=self.selected_node_list, problems=self.problems, open_flag=True)
        else:
            reward = -self._get_travel_distance(selected_node_list=self.selected_node_list, problems=self.problems)
    else:
        reward = self.dummy_flag_long
    next_state = {'ninf_mask': self.ninf_mask, 'selected_count': self.selected_count, 'selected_node_list': self.selected_node_list, 'reward': reward, 'done': done}
    if self.method_name == 'elg' and self.current_node is not None:
        local_feature = self._get_local_feature()
        out = TensorDict({'action': self.current_node, 'first_node': self.first_node, 'next': next_state, 'local_feature': local_feature, 'reward': reward, 'done': done}, batch_size=self.batch_size)
    elif self.method_name == 'lehd':
        out = TensorDict({'action': self.current_node, 'first_node': self.first_node, 'next': next_state, 'partial_length': torch.zeros(self.batch_size, dtype=torch.int) + self.problems.shape[1], 'reward': reward, 'done': done}, batch_size=self.batch_size)
    else:
        out = TensorDict({'action': self.current_node, 'first_node': self.first_node, 'next': next_state, 'reward': reward, 'done': done}, batch_size=self.batch_size)
    return out

# Component: TSPEnv._get_travel_distance
def _get_travel_distance(self, problems=None, selected_node_list=None, batch_size=None, pomo_size=None, open_flag=False):
    if problems is None:
        problems = self.problems
    if selected_node_list is None:
        selected_node_list = self.selected_node_list
    if batch_size is None:
        batch_size = self.env_batch_size
    if pomo_size is None:
        pomo_size = self.pomo_size
    problem_size = problems.shape[1]
    gathering_index = selected_node_list.unsqueeze(3).expand(batch_size, -1, problem_size, 2)
    if self.lib_data is not None and problem_size == self.lib_data['data'].shape[1]:
        seq_expanded = self.lib_data['data'][:, None, :, :].expand(batch_size, pomo_size, problem_size, 2)
    elif self.aug_flag is True:
        seq_expanded = self.raw_problems[:, None, :, :].repeat(self.aug_factor, pomo_size, 1, 1)
    else:
        seq_expanded = problems[:, None, :, :].expand(batch_size, pomo_size, problem_size, 2)
    ordered_seq = seq_expanded.gather(dim=2, index=gathering_index)
    rolled_seq = ordered_seq.roll(dims=2, shifts=-1)
    segment_lengths_raw = ((ordered_seq - rolled_seq) ** 2).sum(3).sqrt()
    if self.lib_data is not None and 'edge_weight_type' in self.lib_data:
        if self.lib_data['edge_weight_type'] == 'CEIL_2D':
            segment_lengths = torch.ceil(segment_lengths_raw)
        elif self.lib_data['edge_weight_type'] == 'EUC_2D':
            segment_lengths = torch.floor(segment_lengths_raw + 0.5)
    else:
        segment_lengths = segment_lengths_raw
    if open_flag:
        travel_distances = segment_lengths[:, :, :-1].sum(2)
    else:
        travel_distances = segment_lengths.sum(2)
    return travel_distances

Solver implementation role: encoder

# Component: MTL_Encoder
class MTL_Encoder(nn.Module):

    def __init__(self, **model_params):
        super().__init__()
        self.model_params = model_params
        embedding_dim = self.model_params['embedding_dim']
        hidden_dim = self.model_params['ff_hidden_dim']
        encoder_layer_num = self.model_params['encoder_layer_num']
        if self.model_params['num_experts'] > 1 and 'Raw' in self.model_params['expert_loc']:
            self.embedding_depot = MoE(input_size=2, output_size=embedding_dim, num_experts=self.model_params['num_experts'], k=self.model_params['topk'], T=1.0, noisy_gating=True, routing_level=self.model_params['routing_level'], routing_method=self.model_params['routing_method'], moe_model='Linear')
            self.embedding_node = MoE(input_size=5, output_size=embedding_dim, num_experts=self.model_params['num_experts'], k=self.model_params['topk'], T=1.0, noisy_gating=True, routing_level=self.model_params['routing_level'], routing_method=self.model_params['routing_method'], moe_model='Linear')
        else:
            self.embedding_depot = nn.Linear(2, embedding_dim)
            self.embedding_node = nn.Linear(5, embedding_dim)
        self.layers = nn.ModuleList([EncoderLayer(i, **model_params) for i in range(encoder_layer_num)])

    def forward(self, depot_xy, node_xy_demand_tw):
        moe_loss = 0
        if isinstance(self.embedding_depot, MoE) or isinstance(self.embedding_node, MoE):
            (embedded_depot, loss_depot) = self.embedding_depot(depot_xy)
            (embedded_node, loss_node) = self.embedding_node(node_xy_demand_tw)
            moe_loss = moe_loss + loss_depot + loss_node
        else:
            embedded_depot = self.embedding_depot(depot_xy)
            embedded_node = self.embedding_node(node_xy_demand_tw)
        out = torch.cat((embedded_depot, embedded_node), dim=1)
        for layer in self.layers:
            (out, loss) = layer(out)
            moe_loss = moe_loss + loss
        return (out, moe_loss)

# Component: EncoderLayer
class EncoderLayer(nn.Module):

    def __init__(self, depth=0, **model_params):
        super().__init__()
        self.model_params = model_params
        embedding_dim = self.model_params['embedding_dim']
        head_num = self.model_params['head_num']
        qkv_dim = self.model_params['qkv_dim']
        self.Wq = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.Wk = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.Wv = nn.Linear(embedding_dim, head_num * qkv_dim, bias=False)
        self.multi_head_combine = nn.Linear(head_num * qkv_dim, embedding_dim)
        self.addAndNormalization1 = Add_And_Normalization_Module(**model_params)
        if self.model_params['num_experts'] > 1 and 'Enc{}'.format(depth) in self.model_params['expert_loc']:
            self.feedForward = MoE(input_size=embedding_dim, output_size=embedding_dim, num_experts=self.model_params['num_experts'], hidden_size=self.model_params['ff_hidden_dim'], k=self.model_params['topk'], T=1.0, noisy_gating=True, routing_level=self.model_params['routing_level'], routing_method=self.model_params['routing_method'], moe_model='MLP')
        else:
            self.feedForward = FeedForward(**model_params)
        self.addAndNormalization2 = Add_And_Normalization_Module(**model_params)

    def forward(self, input1):
        (head_num, moe_loss) = (self.model_params['head_num'], 0)
        q = reshape_by_heads(self.Wq(input1), head_num=head_num)
        k = reshape_by_heads(self.Wk(input1), head_num=head_num)
        v = reshape_by_heads(self.Wv(input1), head_num=head_num)
        if self.model_params['norm_loc'] == 'norm_last':
            out_concat = multi_head_attention(q, k, v)
            multi_head_out = self.multi_head_combine(out_concat)
            out1 = self.addAndNormalization1(input1, multi_head_out)
            (out2, moe_loss) = self.feedForward(out1)
            out3 = self.addAndNormalization2(out1, out2)
        else:
            out1 = self.addAndNormalization1(None, input1)
            multi_head_out = self.multi_head_combine(out1)
            input2 = input1 + multi_head_out
            out2 = self.addAndNormalization2(None, input2)
            (out2, moe_loss) = self.feedForward(out2)
            out3 = input2 + out2
        return (out3, moe_loss)

# Component: FeedForward
class FeedForward(nn.Module):

    def __init__(self, **model_params):
        super().__init__()
        embedding_dim = model_params['embedding_dim']
        ff_hidden_dim = model_params['ff_hidden_dim']
        self.W1 = nn.Linear(embedding_dim, ff_hidden_dim)
        self.W2 = nn.Linear(ff_hidden_dim, embedding_dim)

    def forward(self, input1):
        return (self.W2(F.relu(self.W1(input1))), 0)

# Component: Add_And_Normalization_Module
class Add_And_Normalization_Module(nn.Module):

    def __init__(self, **model_params):
        super().__init__()
        embedding_dim = model_params['embedding_dim']
        self.add = True if 'norm_loc' in model_params.keys() and model_params['norm_loc'] == 'norm_last' else False
        if model_params['norm'] == 'batch':
            self.norm = nn.BatchNorm1d(embedding_dim, affine=True, track_running_stats=True)
        elif model_params['norm'] == 'batch_no_track':
            self.norm = nn.BatchNorm1d(embedding_dim, affine=True, track_running_stats=False)
        elif model_params['norm'] == 'instance':
            self.norm = nn.InstanceNorm1d(embedding_dim, affine=True, track_running_stats=False)
        elif model_params['norm'] == 'layer':
            self.norm = nn.LayerNorm(embedding_dim)
        elif model_params['norm'] == 'rezero':
            self.norm = torch.nn.Parameter(torch.Tensor([0.0]), requires_grad=True)
        else:
            self.norm = None

    def forward(self, input1=None, input2=None):
        if isinstance(self.norm, nn.InstanceNorm1d):
            added = input1 + input2 if self.add else input2
            transposed = added.transpose(1, 2)
            normalized = self.norm(transposed)
            back_trans = normalized.transpose(1, 2)
        elif isinstance(self.norm, nn.BatchNorm1d):
            added = input1 + input2 if self.add else input2
            (batch, problem, embedding) = added.size()
            normalized = self.norm(added.reshape(batch * problem, embedding))
            back_trans = normalized.reshape(batch, problem, embedding)
        elif isinstance(self.norm, nn.LayerNorm):
            added = input1 + input2 if self.add else input2
            back_trans = self.norm(added)
        elif isinstance(self.norm, nn.Parameter):
            back_trans = input1 + self.norm * input2 if self.add else self.norm * input2
        else:
            back_trans = input1 + input2 if self.add else input2
        return back_trans

# Component: SparseDispatcher
class SparseDispatcher(object):

    def __init__(self, num_experts, gates, routing_level='node'):
        self._gates = gates
        self._num_experts = num_experts
        self._routing_level = routing_level
        (sorted_experts, index_sorted_experts) = torch.nonzero(gates).sort(0)
        (_, self._expert_index) = sorted_experts.split(1, dim=1)
        self._batch_index = torch.nonzero(gates)[index_sorted_experts[:, 1], 0]
        self._part_sizes = (gates > 0).sum(0).tolist()
        gates_exp = gates[self._batch_index.flatten()]
        self._nonzero_gates = torch.gather(gates_exp, 1, self._expert_index)

    def dispatch(self, inp):
        inp_exp = inp[self._batch_index].squeeze(1)
        return torch.split(inp_exp, self._part_sizes, dim=0)

    def combine(self, expert_out, multiply_by_gates=True):
        stitched = torch.cat(expert_out, 0)
        if multiply_by_gates:
            if self._routing_level == 'node':
                stitched = stitched.mul(self._nonzero_gates)
            elif self._routing_level == 'instance':
                stitched = stitched.mul(self._nonzero_gates.unsqueeze(1))
        if self._routing_level == 'node':
            zeros = torch.zeros(self._gates.size(0), expert_out[-1].size(-1), requires_grad=True, device=stitched.device)
        elif self._routing_level == 'instance':
            zeros = torch.zeros(self._gates.size(0), expert_out[-1].size(1), expert_out[-1].size(-1), requires_grad=True, device=stitched.device)
        combined = zeros.index_add(0, self._batch_index, stitched.float())
        combined[combined == 0] = np.finfo(float).eps
        return combined

    def expert_to_gates(self):
        return torch.split(self._nonzero_gates, self._part_sizes, dim=0)

# Component: MLP
class MLP(nn.Module):

    def __init__(self, input_size=128, output_size=128, hidden_size=512):
        super(MLP, self).__init__()
        self.fc1 = nn.Linear(input_size, hidden_size)
        self.fc2 = nn.Linear(hidden_size, output_size)
        self.relu = nn.ReLU()

    def forward(self, x):
        return self.fc2(self.relu(self.fc1(x)))

# Component: MoE
class MoE(nn.Module):

    def __init__(self, input_size, output_size, num_experts, hidden_size=None, k=1, T=1.0, noisy_gating=True, routing_level='node', routing_method='input_choice', moe_model='MLP'):
        super(MoE, self).__init__()
        self.noisy_gating = noisy_gating
        self.routing_level = routing_level
        self.routing_method = routing_method
        self.num_experts = num_experts
        self.output_size = output_size
        self.input_size = input_size
        self.hidden_size = hidden_size
        self.k = k
        self.T = T
        if moe_model == 'MLP':
            self.experts = nn.ModuleList([MLP(self.input_size, self.output_size, self.hidden_size) for _ in range(self.num_experts)])
        elif moe_model == 'Linear':
            self.experts = nn.ModuleList([nn.Linear(self.input_size, self.output_size) for _ in range(self.num_experts)])
        else:
            raise NotImplementedError
        if routing_method == 'soft_moe':
            self.w_gate = nn.Parameter(torch.zeros(input_size, num_experts * k), requires_grad=True)
        else:
            self.w_gate = nn.Parameter(torch.zeros(input_size, num_experts), requires_grad=True)
        self.w_noise = nn.Parameter(torch.zeros(input_size, num_experts), requires_grad=True)
        if not (routing_level in ['node', 'instance'] and routing_method == 'input_choice'):
            torch.nn.init.kaiming_uniform_(self.w_gate, a=math.sqrt(5))
        self.softplus = nn.Softplus()
        self.softmax = nn.Softmax(-1)
        self.register_buffer('mean', torch.tensor([0.0]))
        self.register_buffer('std', torch.tensor([1.0]))
        assert self.k <= self.num_experts

    def cv_squared(self, x):
        eps = 1e-10
        if x.shape[0] == 1:
            return torch.tensor([0], device=x.device, dtype=x.dtype)
        return x.float().var() / (x.float().mean() ** 2 + eps)

    def _gates_to_load(self, gates):
        return (gates > 0).sum(0)

    def _prob_in_top_k(self, clean_values, noisy_values, noise_stddev, noisy_top_values):
        batch = clean_values.size(0)
        m = noisy_top_values.size(1)
        top_values_flat = noisy_top_values.flatten()
        threshold_positions_if_in = torch.arange(batch, device=clean_values.device) * m + self.k
        threshold_if_in = torch.unsqueeze(torch.gather(top_values_flat, 0, threshold_positions_if_in), 1)
        is_in = torch.gt(noisy_values, threshold_if_in)
        threshold_positions_if_out = threshold_positions_if_in - 1
        threshold_if_out = torch.unsqueeze(torch.gather(top_values_flat, 0, threshold_positions_if_out), 1)
        normal = Normal(self.mean, self.std)
        prob_if_in = normal.cdf((clean_values - threshold_if_in) / noise_stddev)
        prob_if_out = normal.cdf((clean_values - threshold_if_out) / noise_stddev)
        prob = torch.where(is_in, prob_if_in, prob_if_out)
        return prob

    def noisy_top_k_gating(self, x, train, noise_epsilon=0.01):
        x = x.mean(1) if self.routing_level == 'instance' else x
        clean_logits = x @ self.w_gate
        if self.noisy_gating and train:
            raw_noise_stddev = x @ self.w_noise
            noise_stddev = self.softplus(raw_noise_stddev) + noise_epsilon
            noisy_logits = clean_logits + torch.randn_like(clean_logits) * noise_stddev
            logits = noisy_logits
        else:
            logits = clean_logits
        (top_logits, top_indices) = logits.topk(min(self.k + 1, self.num_experts), dim=-1)
        top_k_logits = top_logits[..., :self.k]
        top_k_indices = top_indices[..., :self.k]
        top_k_gates = self.softmax(top_k_logits / self.T)
        zeros = torch.zeros_like(logits, requires_grad=True)
        gates = zeros.scatter(-1, top_k_indices, top_k_gates)
        if self.noisy_gating and self.k < self.num_experts and train:
            load = self._prob_in_top_k(clean_logits, noisy_logits, noise_stddev, top_logits).sum(0)
        else:
            load = self._gates_to_load(gates)
        return (gates, load)

    def problem_top_k_gating(self, x, prob_emb=None):
        x = x.mean(0).mean(0).unsqueeze(0) + prob_emb if prob_emb is not None else x.mean(0).mean(0).unsqueeze(0)
        logits = x @ self.w_gate
        (top_logits, top_indices) = logits.topk(min(self.k + 1, self.num_experts), dim=-1)
        selected_logits = top_logits[..., :self.k].squeeze(0)
        selected_indices = top_indices[..., :self.k].squeeze(0)
        selected_gates = self.softmax(selected_logits / self.T)
        return (selected_indices, selected_gates)

    def expert_gating(self, x, k):
        x = x.mean(1) if self.routing_level == 'instance' else x
        logits = x @ self.w_gate
        S = torch.softmax(logits, dim=0)
        (G, I) = torch.topk(S.T, k=k, dim=-1)
        P = nn.functional.one_hot(I, num_classes=x.size(0))
        return (G, I, P)

    def forward(self, x, loss_coef=0.001, prob_emb=None):
        assert self.routing_level in ['node', 'instance', 'problem'], 'Unsupported Routing Level!'
        output_shape = list(x.size()[:-1]) + [self.output_size]
        if self.routing_level in ['instance', 'problem']:
            assert x.dim() == 3
        elif self.routing_level == 'node':
            x = x.reshape(-1, self.input_size) if x.dim() != 2 else x
        if self.routing_level == 'problem':
            if self.routing_method != 'random':
                (expert_ids, gates) = self.problem_top_k_gating(x, prob_emb)
            else:
                expert_ids = torch.randperm(self.num_experts)[:self.k]
                gates = torch.Tensor([1.0 / self.k for _ in range(self.k)])
            expert_outputs = []
            for i in expert_ids.tolist():
                expert_outputs.append(self.experts[i](x).unsqueeze(0))
            expert_outputs = torch.cat(expert_outputs, 0)
            y = (expert_outputs * gates.reshape(-1, 1, 1, 1)).sum(0)
            return (y, 0)
        elif self.routing_level in ['node', 'instance']:
            if self.routing_method == 'input_choice':
                (gates, load) = self.noisy_top_k_gating(x, self.training)
                importance = gates.sum(0)
                loss = self.cv_squared(importance) + self.cv_squared(load)
                loss *= loss_coef
                dispatcher = SparseDispatcher(self.num_experts, gates, routing_level=self.routing_level)
                expert_inputs = dispatcher.dispatch(x)
                expert_outputs = [self.experts[i](expert_inputs[i]) for i in range(self.num_experts)]
                y = dispatcher.combine(expert_outputs)
                return (y.reshape(output_shape), loss)
            elif self.routing_method == 'expert_choice':
                assert self.input_size == self.output_size
                k = int(x.size(0) * self.k / self.num_experts)
                expert_inputs_shape = [self.num_experts, k] + list(x.size()[1:])
                (G, I, P) = self.expert_gating(x, k)
                expert_inputs = P.float() @ x.reshape(P.size(-1), -1)
                expert_inputs = expert_inputs.reshape(expert_inputs_shape)
                expert_outputs = [self.experts[i](expert_inputs[i]) for i in range(self.num_experts)]
                expert_outputs = torch.stack(expert_outputs, 0)
                output = torch.einsum('ijl,ij,ijd->ld', P, G, expert_outputs.reshape(self.num_experts, k, -1))
                return (output.reshape(output_shape), 0)
            elif self.routing_method == 'soft_moe':
                x_ = x.mean(1) if self.routing_level == 'instance' else x
                logits = x_ @ self.w_gate
                expert_inputs_shape = [logits.size(-1)] + list(x.size()[1:])
                expert_inputs = torch.softmax(logits, dim=0).T @ x.reshape(logits.size(0), -1)
                expert_inputs = expert_inputs.reshape(expert_inputs_shape)
                expert_outputs = [self.experts[i](expert_inputs[i * self.k:(i + 1) * self.k]) for i in range(self.num_experts)]
                expert_outputs = torch.stack(expert_outputs, 0).reshape(self.num_experts * self.k, -1)
                output = torch.softmax(logits, dim=-1) @ expert_outputs
                return (output.reshape(output_shape), 0)
            elif self.routing_method == 'random':
                zeros = torch.zeros((x.size(0), self.num_experts), requires_grad=True)
                random_indices = torch.argsort(torch.rand(x.size(0), self.num_experts), dim=-1)[:, :self.k]
                gates = zeros.scatter(-1, random_indices, 1.0 / self.k)
                dispatcher = SparseDispatcher(self.num_experts, gates, routing_level=self.routing_level)
                expert_inputs = dispatcher.dispatch(x)
                expert_outputs = [self.experts[i](expert_inputs[i]) for i in range(self.num_experts)]
                y = dispatcher.combine(expert_outputs)
                return (y.reshape(output_shape), 0)
            else:
                raise NotImplementedError

# Component: collate_problem_batch
def collate_problem_batch(dataset: str, dataset_obj, indices: Sequence[int]) -> Tuple[Tuple[torch.Tensor, ...], int]:
    problem = dataset_problem(dataset)
    samples = [dataset_obj[i] for i in indices]
    scale = infer_scale_from_sample(dataset, samples[0])
    if problem == 'CVRP':
        depot = []
        loc = []
        demand = []
        for sample in samples:
            depot.append(normalize_tensor_like(sample['depot']).squeeze(0))
            loc.append(normalize_tensor_like(sample['loc']).squeeze(0))
            demand.append(normalize_tensor_like(sample['demand']).squeeze(0))
        return ((torch.stack(depot, dim=0), torch.stack(loc, dim=0), torch.stack(demand, dim=0)), scale)
    depot_xy = []
    node_xy = []
    node_demand = []
    route_limit = []
    service_time = []
    tw_start = []
    tw_end = []
    for sample in samples:
        depot_xy.append(normalize_tensor_like(sample['depot_xy']))
        node_xy.append(normalize_tensor_like(sample['node_xy']))
        node_demand.append(normalize_tensor_like(sample['node_demand']))
        if 'route_limit' in sample:
            route_limit.append(float(sample['route_limit']))
        if 'service_time' in sample:
            service_time.append(normalize_tensor_like(sample['service_time']))
            tw_start.append(normalize_tensor_like(sample['tw_start']))
            tw_end.append(normalize_tensor_like(sample['tw_end']))
    depot_xy_t = torch.stack(depot_xy, dim=0)
    node_xy_t = torch.stack(node_xy, dim=0)
    node_demand_t = torch.stack(node_demand, dim=0)
    if service_time and route_limit:
        return ((depot_xy_t, node_xy_t, node_demand_t, torch.tensor(route_limit, dtype=torch.float32), torch.stack(service_time, dim=0), torch.stack(tw_start, dim=0), torch.stack(tw_end, dim=0)), scale)
    if service_time:
        return ((depot_xy_t, node_xy_t, node_demand_t, torch.stack(service_time, dim=0), torch.stack(tw_start, dim=0), torch.stack(tw_end, dim=0)), scale)
    if route_limit:
        return ((depot_xy_t, node_xy_t, node_demand_t, torch.tensor(route_limit, dtype=torch.float32)), scale)
    return ((depot_xy_t, node_xy_t, node_demand_t), scale)

Solver implementation role: encoder

# Component: RouteFinderEncoder
class RouteFinderEncoder(nn.Module):

    def __init__(self, init_embedding: nn.Module=None, num_heads: int=8, embed_dim: int=128, num_layers: int=6, feedforward_hidden: int=512, normalization: str='instance', use_prenorm: bool=False, use_post_layers_norm: bool=False, parallel_gated_kwargs: dict=None, **transformer_kwargs):
        super(RouteFinderEncoder, self).__init__()
        if init_embedding is None:
            init_embedding = MTVRPInitEmbeddingRouteFinder(embed_dim=embed_dim)
        else:
            log.warning('Using custom init_embedding')
        self.init_embedding = init_embedding
        self.layers = nn.Sequential(*(TransformerBlock(embed_dim=embed_dim, num_heads=num_heads, normalization=normalization, use_prenorm=use_prenorm, feedforward_hidden=feedforward_hidden, parallel_gated_kwargs=parallel_gated_kwargs, **transformer_kwargs) for _ in range(num_layers)))
        self.post_layers_norm = Normalization(embed_dim, normalization) if use_post_layers_norm else None

    def forward(self, td: Tensor, mask: Union[Tensor, None]=None) -> Tuple[Tensor, Tensor]:
        init_h = self.init_embedding(td)
        h = init_h
        for layer in self.layers:
            h = layer(h, mask)
        if self.post_layers_norm is not None:
            h = self.post_layers_norm(h)
        return (h, init_h)

# Component: RMSNorm
class RMSNorm(nn.Module):

    def __init__(self, dim: int, eps: float=1e-05, **kwargs):
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.ones(dim))

    def _norm(self, x):
        return x * torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)

    def forward(self, x):
        output = self._norm(x.float()).type_as(x)
        return output * self.weight

# Component: Normalization
class Normalization(nn.Module):

    def __init__(self, embed_dim, normalization='batch'):
        super(Normalization, self).__init__()
        if normalization != 'layer':
            normalizer_class = {'batch': nn.BatchNorm1d, 'instance': nn.InstanceNorm1d, 'rms': RMSNorm}.get(normalization, None)
            self.normalizer = normalizer_class(embed_dim, affine=True) if normalizer_class is not None else None
        else:
            self.normalizer = 'layer'
        if self.normalizer is None:
            log.error('Normalization type {} not found. Skipping normalization.'.format(normalization))

    def forward(self, x):
        if isinstance(self.normalizer, nn.BatchNorm1d):
            return self.normalizer(x.view(-1, x.size(-1))).view(*x.size())
        elif isinstance(self.normalizer, nn.InstanceNorm1d):
            return self.normalizer(x.permute(0, 2, 1)).permute(0, 2, 1)
        elif self.normalizer == 'layer':
            return (x - x.mean((1, 2)).view(-1, 1, 1)) / torch.sqrt(x.var((1, 2)).view(-1, 1, 1) + 1e-05)
        elif isinstance(self.normalizer, RMSNorm):
            return self.normalizer(x)
        else:
            assert self.normalizer is None, 'Unknown normalizer type {}'.format(self.normalizer)
            return x

# Component: ParallelGatedMLP
class ParallelGatedMLP(nn.Module):

    def __init__(self, hidden_size: int=128, inner_size_multiple_of: int=256, mlp_activation: str='silu', model_parallel_size: int=1):
        super().__init__()
        multiple_of = inner_size_multiple_of
        self.act_type = mlp_activation
        if self.act_type == 'gelu':
            self.act = F.gelu
        elif self.act_type == 'silu':
            self.act = F.silu
        else:
            raise NotImplementedError
        self.multiple_of = multiple_of * model_parallel_size
        inner_size = int(2 * hidden_size * 4 / 3)
        inner_size = self.multiple_of * ((inner_size + self.multiple_of - 1) // self.multiple_of)
        self.l1 = nn.Linear(in_features=hidden_size, out_features=inner_size, bias=False)
        self.l2 = nn.Linear(in_features=hidden_size, out_features=inner_size, bias=False)
        self.l3 = nn.Linear(in_features=inner_size, out_features=hidden_size, bias=False)

    def forward(self, z):
        (z1, z2) = (self.l1(z), self.l2(z))
        return self.l3(self.act(z1) * z2)

# Component: TransformerBlock
class TransformerBlock(nn.Module):

    def __init__(self, embed_dim: int=128, num_heads: int=8, feedforward_hidden: Optional[int]=None, normalization: Optional[str]='instance', use_prenorm: bool=False, bias: bool=True, sdpa_fn: Optional[Callable]=None, moe_kwargs: Optional[dict]=None, parallel_gated_kwargs: Optional[dict]=None):
        super(TransformerBlock, self).__init__()
        feedforward_hidden = 4 * embed_dim if feedforward_hidden is None else feedforward_hidden
        num_neurons = [feedforward_hidden] if feedforward_hidden > 0 else []
        if moe_kwargs is not None:
            ffn = MoE(embed_dim, embed_dim, num_neurons=num_neurons, **moe_kwargs)
        elif parallel_gated_kwargs is not None:
            ffn = ParallelGatedMLP(embed_dim, **parallel_gated_kwargs)
        else:
            ffn = MLP(input_dim=embed_dim, output_dim=embed_dim, num_neurons=num_neurons, hidden_act='ReLU')
        self.norm_attn = Normalization(embed_dim, normalization) if normalization is not None else lambda x: x
        self.attention = MultiHeadAttention(embed_dim, num_heads, bias=bias, sdpa_fn=sdpa_fn)
        self.norm_ffn = Normalization(embed_dim, normalization) if normalization is not None else lambda x: x
        self.ffn = ffn
        self.use_prenorm = use_prenorm

    def forward(self, x: Tensor, mask: Optional[Tensor]=None) -> Tensor:
        if self.use_prenorm:
            h = x + self.attention(self.norm_attn(x), mask)
            h = h + self.ffn(self.norm_ffn(h))
        else:
            h = self.norm_attn(x + self.attention(x, mask))
            h = self.norm_ffn(h + self.ffn(h))
        return h

# Component: _to_tensor
def _to_tensor(x) -> torch.Tensor:
    t = torch.as_tensor(x)
    if t.ndim > 0 and t.shape[0] == 1:
        t = t.squeeze(0)
    return t.detach().cpu()

# Component: _float_scalar
def _float_scalar(x, default: float=0.0) -> float:
    if x is None:
        return default
    t = torch.as_tensor(x).detach().cpu().reshape(-1)
    return float(t[0].item()) if t.numel() else default

# Component: _canonical_vrp_item
def _canonical_vrp_item(dataset_name: str, item) -> Dict:
    ident = parse_dataset_identity(dataset_name)
    variant = ident['variant']
    if ident['problem'] == 'CVRP':
        depot_xy = _to_tensor(item['depot'])
        node_xy = _to_tensor(item['loc'])
        node_demand = _to_tensor(item['demand']).float()
        if node_xy.ndim == 2 and node_xy.shape[0] == node_demand.shape[0] and (node_xy.shape[0] >= 1) and torch.allclose(node_xy[:1].float(), depot_xy.float()) and (float(node_demand[0].item()) == 0.0):
            node_xy = node_xy[1:]
            node_demand = node_demand[1:]
        capacity = 1.0
        route_limit = None
        service_time = None
        tw_start = None
        tw_end = None
    else:
        depot_xy = _to_tensor(item['depot_xy'])
        node_xy = _to_tensor(item['node_xy'])
        node_demand = _to_tensor(item['node_demand']).float()
        capacity = _float_scalar(item.get('capacity'), default=1.0)
        route_limit = item.get('route_limit')
        service_time = item.get('service_time')
        tw_start = item.get('tw_start')
        tw_end = item.get('tw_end')
    if depot_xy.ndim == 1:
        depot_xy = depot_xy.unsqueeze(0)
    linehaul = node_demand.clamp(min=0)
    backhaul = (-node_demand).clamp(min=0)
    locs = torch.cat([depot_xy.float(), node_xy.float()], dim=0)
    depot_zeros = torch.zeros(1, dtype=torch.float32)
    demand_linehaul = linehaul.float()
    demand_backhaul = backhaul.float()
    if service_time is None:
        service_time_full = torch.zeros(locs.shape[0], dtype=torch.float32)
    else:
        service_time_full = torch.cat([depot_zeros, _to_tensor(service_time).float()], dim=0)
    if tw_start is None or tw_end is None:
        time_windows = torch.zeros(locs.shape[0], 2, dtype=torch.float32)
        time_windows[:, 1] = float('inf')
    else:
        tw_start_t = _to_tensor(tw_start).float()
        tw_end_t = _to_tensor(tw_end).float()
        depot_tw = torch.tensor([[0.0, float('inf')]], dtype=torch.float32)
        customer_tw = torch.stack([tw_start_t, tw_end_t], dim=-1)
        time_windows = torch.cat([depot_tw, customer_tw], dim=0)
    open_route = torch.tensor([variant.startswith('ovrp')], dtype=torch.bool)
    distance_limit = torch.tensor([_float_scalar(route_limit, default=float('inf'))], dtype=torch.float32)
    vehicle_capacity = torch.tensor([1.0], dtype=torch.float32)
    capacity_original = torch.tensor([capacity], dtype=torch.float32)
    speed = torch.tensor([1.0], dtype=torch.float32)
    return {'scale': int(node_xy.shape[0]), 'variant': variant, 'locs': locs, 'demand_linehaul': demand_linehaul, 'demand_backhaul': demand_backhaul, 'distance_limit': distance_limit, 'time_windows': time_windows, 'service_time': service_time_full, 'vehicle_capacity': vehicle_capacity, 'capacity_original': capacity_original, 'open_route': open_route, 'speed': speed}

